package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"

	"github.com/charmbracelet/huh"

	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// IsAccessibleMode returns true if accessibility mode should be enabled.
// This checks the ACCESSIBLE environment variable.
// Set ACCESSIBLE=1 (or any non-empty value) to enable accessible mode,
// which uses simpler prompts that work better with screen readers.
func IsAccessibleMode() bool {
	return os.Getenv("ACCESSIBLE") != ""
}

// entireTheme returns the Dracula theme for consistent styling.
func entireTheme() *huh.Theme {
	return huh.ThemeDracula()
}

// NewAccessibleForm creates a new huh form with accessibility mode
// enabled if the ACCESSIBLE environment variable is set.
// Note: WithAccessible() is only available on forms, not individual fields.
// Always wrap confirmations and other prompts in a form to enable accessibility.
func NewAccessibleForm(groups ...*huh.Group) *huh.Form {
	form := huh.NewForm(groups...).WithTheme(entireTheme())
	if IsAccessibleMode() {
		form = form.WithAccessible(true)
	}
	return form
}

// handleFormCancellation handles cancellation from huh form prompts.
// User abort (Ctrl+C) and timeout both print a cancelled message and return nil.
// Other errors are wrapped with the action name for context.
func handleFormCancellation(w io.Writer, action string, err error) error {
	if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, huh.ErrTimeout) {
		fmt.Fprintf(w, "%s cancelled.\n", action)
		return nil
	}
	return fmt.Errorf("%s prompt failed: %w", action, err)
}

// printSessionCommand writes a single session resume command line to w.
// It appends a "(most recent)" label to the last entry in a multi-session list,
// and a "# prompt" comment when a prompt is available.
func printSessionCommand(w io.Writer, resumeCmd, prompt string, isMulti, isLast bool) {
	comment := ""
	if isMulti && isLast {
		if prompt != "" {
			comment = fmt.Sprintf("  # %s (most recent)", prompt)
		} else {
			comment = "  # (most recent)"
		}
	} else if prompt != "" {
		comment = "  # " + prompt
	}
	fmt.Fprintf(w, "  %s%s\n", resumeCmd, comment)
}

// fileExists checks if a file exists
func fileExists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}

// copyFile copies a file from src to dst using os.Root for traversal-resistant
// writes (Go 1.24+). dst must be absolute and reside under either the repo
// worktree root, the user's home directory (for agent session dirs such as
// ~/.claude/), or the system temp directory (used during tests).
// The kernel enforces that the write cannot escape the allowed directory,
// eliminating TOCTOU races and symlink escapes.
func copyFile(src, dst string) error {
	src = filepath.Clean(src)
	dst = filepath.Clean(dst)

	if !filepath.IsAbs(dst) {
		return fmt.Errorf("copyFile: dst must be absolute, got %q", dst)
	}

	input, err := os.ReadFile(src)
	if err != nil {
		return err //nolint:wrapcheck // already present in codebase
	}

	root, relPath, err := openAllowedRoot(dst)
	if err != nil {
		return err
	}
	defer root.Close()

	if err := osroot.WriteFile(root, relPath, input, 0o600); err != nil {
		return fmt.Errorf("failed to write file: %w", err)
	}
	return nil
}

// openAllowedRoot finds the allowed root directory that contains dst and returns
// an os.Root handle along with the relative path within that root.
// Allowed directories: repo worktree root, user home, system temp dir.
// dst is resolved through symlinks before matching to handle macOS /var → /private/var.
func openAllowedRoot(dst string) (*os.Root, string, error) {
	allowed := allowedRootDirs()

	// Resolve the directory portion of dst through symlinks so that e.g.
	// /var/folders/... matches /private/var/folders/... on macOS.
	// Only the parent directory is resolved; the final component may not exist yet.
	resolvedDst := dst
	if r, err := filepath.EvalSymlinks(filepath.Dir(dst)); err == nil {
		resolvedDst = filepath.Join(r, filepath.Base(dst))
	}

	for _, dir := range allowed {
		if !paths.IsSubpath(dir, resolvedDst) {
			continue
		}
		rel, err := filepath.Rel(dir, resolvedDst)
		if err != nil {
			continue
		}
		root, err := os.OpenRoot(dir)
		if err != nil {
			return nil, "", fmt.Errorf("openAllowedRoot: failed to open root %q: %w", dir, err)
		}
		return root, rel, nil
	}

	return nil, "", fmt.Errorf("openAllowedRoot: dst %q is outside allowed directories", dst)
}

// allowedRootDirs returns the list of directories that copyFile may write to.
// Directories are resolved through symlinks so they match resolved dst paths.
func allowedRootDirs() []string {
	allowed := make([]string, 0, 3)

	if repoRoot, err := paths.WorktreeRoot(context.Background()); err == nil {
		allowed = appendResolved(allowed, repoRoot)
	}
	if home, err := os.UserHomeDir(); err == nil {
		allowed = appendResolved(allowed, home)
	}
	if tmpDir := os.TempDir(); tmpDir != "" {
		allowed = appendResolved(allowed, tmpDir)
	}

	return allowed
}

// appendResolved appends dir to the list after resolving symlinks.
// Falls back to the original path if symlink resolution fails.
func appendResolved(dirs []string, dir string) []string {
	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
		return append(dirs, resolved)
	}
	return append(dirs, dir)
}

package cli

import (
	"errors"
	"fmt"
	"io"
	"os"
	"strings"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/entireio/cli/cmd/entire/cli/auth"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/search"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
	"github.com/spf13/cobra"
)

func newSearchCmd() *cobra.Command {
	var (
		jsonOutput bool
		limitFlag  int
		pageFlag   int
		authorFlag string
		dateFlag   string
		branchFlag string
		repoFlag   string
	)

	cmd := &cobra.Command{
		Use:   "search [query]",
		Short: "Search checkpoints using semantic and keyword matching",
		Long: `Search checkpoints using hybrid search (semantic + keyword),
powered by the Entire search service.

Requires authentication via 'entire login' (GitHub device flow).

Run without arguments to open an interactive search. Results are
displayed in an interactive table. Use --json for machine-readable output.

CLI queries also support inline filters like author:<name>, date:<week|month>,
branch:<name>, repo:<owner/name>, and repo:* to search all accessible repos.`,
		Args:   cobra.ArbitraryArgs,
		Hidden: true,
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			query := strings.Join(args, " ")

			// Extract inline filters (author:, date:, branch:, repo:) from query args
			parsed := search.ParseSearchInput(query)
			query = parsed.Query
			if authorFlag == "" {
				authorFlag = parsed.Author
			}
			if dateFlag == "" {
				dateFlag = parsed.Date
			}
			if branchFlag == "" {
				branchFlag = parsed.Branch
			}
			repos := parsed.Repos
			if repoFlag != "" {
				repos = []string{repoFlag}
			}
			if err := search.ValidateRepoFilters(repos); err != nil {
				return fmt.Errorf("validating repo filter: %w", err)
			}

			w := cmd.OutOrStdout()
			isTerminal := isTerminalWriter(w)
			hasFilters := authorFlag != "" || dateFlag != "" || branchFlag != "" || len(repos) > 0

			// Fast-fail: no query + non-interactive mode = error (before auth/git checks)
			if query == "" && !hasFilters && (jsonOutput || !isTerminal || IsAccessibleMode()) {
				return errors.New("query required when using --json, accessible mode, or piped output. Usage: entire search <query>")
			}

			ghToken, err := auth.LookupCurrentToken()
			if err != nil {
				return fmt.Errorf("reading credentials: %w", err)
			}
			if ghToken == "" {
				return errors.New("not authenticated. Run 'entire login' to authenticate")
			}

			// Get the repo's GitHub remote URL
			repo, err := strategy.OpenRepository(ctx)
			if err != nil {
				cmd.SilenceUsage = true
				fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Run this command from within a git repository.")
				return NewSilentError(err)
			}

			remote, err := repo.Remote("origin")
			if err != nil {
				return fmt.Errorf("could not find 'origin' remote: %w", err)
			}
			urls := remote.Config().URLs
			if len(urls) == 0 {
				return errors.New("origin remote has no URLs configured")
			}

			owner, repoName, err := search.ParseGitHubRemote(urls[0])
			if err != nil {
				return fmt.Errorf("parsing remote URL: %w", err)
			}

			serviceURL := os.Getenv("ENTIRE_SEARCH_URL")
			if serviceURL == "" {
				serviceURL = search.DefaultServiceURL
			}

			searchCfg := search.Config{
				ServiceURL:  serviceURL,
				GitHubToken: ghToken,
				Owner:       owner,
				Repo:        repoName,
				Repos:       repos,
				Query:       query,
				Limit:       limitFlag,
				Page:        pageFlag,
				Author:      authorFlag,
				Date:        dateFlag,
				Branch:      branchFlag,
			}

			// Use wildcard query when only filters are provided
			if query == "" && searchCfg.HasFilters() {
				searchCfg.Query = search.WildcardQuery
			}

			// No query provided + interactive = open TUI with search bar focused
			if query == "" && !searchCfg.HasFilters() {
				searchCfg.Limit = search.MaxLimit
				styles := newStatusStyles(w)
				model := newSearchModel(nil, "", 0, searchCfg, styles)
				model.mode = modeSearch
				model.input.Focus()
				p := tea.NewProgram(model, tea.WithAltScreen())
				if _, err := p.Run(); err != nil {
					return fmt.Errorf("TUI error: %w", err)
				}
				return nil
			}

			// Fetch max results so client-side pagination works.
			// The search API caps results at the limit, so we fetch
			// the maximum and paginate client-side for all output modes.
			requestedLimit := searchCfg.Limit
			requestedPage := searchCfg.Page
			searchCfg.Limit = search.MaxLimit
			searchCfg.Page = 0 // let API default to page 1

			resp, err := search.Search(ctx, searchCfg)
			if err != nil {
				return fmt.Errorf("search failed: %w", err)
			}

			// JSON output: explicit flag or piped/redirected stdout
			if jsonOutput || !isTerminal {
				return writeSearchJSON(w, resp, requestedLimit, requestedPage)
			}

			styles := newStatusStyles(w)

			// Accessible mode: static table
			if IsAccessibleMode() {
				if len(resp.Results) == 0 {
					fmt.Fprintln(w, "No results found.")
					return nil
				}
				renderSearchStatic(w, resp.Results, query, resp.Total, styles)
				return nil
			}

			// Interactive TUI
			model := newSearchModel(resp.Results, query, resp.Total, searchCfg, styles)
			p := tea.NewProgram(model, tea.WithAltScreen())
			if _, err := p.Run(); err != nil {
				return fmt.Errorf("TUI error: %w", err)
			}
			return nil
		},
	}

	cmd.Flags().BoolVar(&jsonOutput, "json", false, "Output as JSON")
	cmd.Flags().IntVar(&limitFlag, "limit", resultsPerPage, "Maximum number of results per page")
	cmd.Flags().IntVar(&pageFlag, "page", 1, "Page number (1-based)")
	cmd.Flags().StringVar(&authorFlag, "author", "", "Filter by author name")
	cmd.Flags().StringVar(&dateFlag, "date", "", "Filter by time period (week or month)")
	cmd.Flags().StringVar(&branchFlag, "branch", "", "Filter by branch name")
	cmd.Flags().StringVar(&repoFlag, "repo", "", "Filter by repository (owner/name or *)")

	return cmd
}

// writeSearchJSON writes client-side paginated search results as JSON.
func writeSearchJSON(w io.Writer, resp *search.Response, limit, page int) error {
	if limit <= 0 {
		limit = resultsPerPage
	}

	total := len(resp.Results)
	totalPages := (total + limit - 1) / limit
	if totalPages < 1 {
		totalPages = 1
	}
	if page < 1 {
		page = 1
	}

	// Slice results for the requested page.
	start := (page - 1) * limit
	end := start + limit
	var pageResults []search.Result
	if start < total {
		if end > total {
			end = total
		}
		pageResults = resp.Results[start:end]
	}
	if pageResults == nil {
		pageResults = []search.Result{}
	}

	out := struct {
		Results    []search.Result `json:"results"`
		Total      int             `json:"total"`
		Page       int             `json:"page"`
		TotalPages int             `json:"total_pages"`
		Limit      int             `json:"limit"`
	}{
		Results:    pageResults,
		Total:      total,
		Page:       page,
		TotalPages: totalPages,
		Limit:      limit,
	}
	data, err := jsonutil.MarshalIndentWithNewline(out, "", "  ")
	if err != nil {
		return fmt.Errorf("marshaling results: %w", err)
	}
	fmt.Fprint(w, string(data))
	return nil
}

