package cli

import (
	"bufio"
	"bytes"
	"context"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/paths"
)

var runGitBlamePorcelain = func(ctx context.Context, repoRoot, path string) (string, error) {
	cmd := exec.CommandContext(ctx, "git", "blame", "--line-porcelain", "--", path)
	cmd.Dir = repoRoot
	var stdout bytes.Buffer
	var stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()
	if err != nil {
		msg := strings.TrimSpace(stderr.String())
		if msg != "" {
			return "", fmt.Errorf("git blame --line-porcelain -- %s: %w: %s", path, err, msg)
		}
		return "", fmt.Errorf("git blame --line-porcelain -- %s: %w", path, err)
	}
	return stdout.String(), nil
}

func loadWhyBlocks(ctx context.Context, path string) ([]whyBlock, error) {
	repoRoot, blamePath, err := resolveWhyBlameTargetPath(ctx, path)
	if err != nil {
		return nil, err
	}

	out, err := runGitBlamePorcelain(ctx, repoRoot, blamePath)
	if err != nil {
		return nil, err
	}
	blocks, err := parseWhyBlamePorcelain(strings.NewReader(out))
	if err != nil {
		return nil, fmt.Errorf("parse git blame output for %s: %w", path, err)
	}
	return blocks, nil
}

func resolveWhyBlameTargetPath(ctx context.Context, userPath string) (string, string, error) {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return "", "", err
	}
	repoRoot = normalizeWhyBlamePath(repoRoot)

	absPath, err := resolveWhyBlameAbsolutePath(repoRoot, userPath)
	if err != nil {
		return "", "", err
	}

	relPath := paths.ToRelativePath(absPath, repoRoot)
	if relPath == "" {
		return "", "", fmt.Errorf("path %q is outside the worktree root", userPath)
	}

	return repoRoot, filepath.ToSlash(relPath), nil
}

func resolveWhyBlameAbsolutePath(repoRoot, userPath string) (string, error) {
	if filepath.IsAbs(userPath) {
		return normalizeWhyBlamePath(userPath), nil
	}

	if _, err := os.Stat(userPath); err == nil {
		absPath, err := filepath.Abs(userPath)
		if err != nil {
			return "", err
		}
		return normalizeWhyBlamePath(absPath), nil
	} else if !os.IsNotExist(err) {
		return "", err
	}

	return normalizeWhyBlamePath(filepath.Join(repoRoot, userPath)), nil
}

func normalizeWhyBlamePath(path string) string {
	if resolved, err := filepath.EvalSymlinks(path); err == nil {
		return resolved
	}
	return filepath.Clean(path)
}

func parseWhyBlamePorcelain(r io.Reader) ([]whyBlock, error) {
	scanner := bufio.NewScanner(r)
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	var (
		blocks []whyBlock
		cur    *whyBlameHeader
	)

	flush := func() error {
		if cur == nil {
			return nil
		}
		if !cur.ContentSeen {
			return fmt.Errorf("truncated blame record for commit %s at line %d", cur.Hash, cur.EndLine)
		}

		block := whyBlock{
			StartLine: cur.EndLine,
			EndLine:   cur.EndLine,
			Commit:    cur.Meta,
			CodeLines: []string{cur.LineText},
			Detail:    whyDetailCommit,
		}

		if len(blocks) > 0 {
			last := &blocks[len(blocks)-1]
			if last.Commit.Hash == block.Commit.Hash && last.EndLine+1 == block.StartLine {
				last.EndLine = block.EndLine
				last.CodeLines = append(last.CodeLines, block.CodeLines...)
				return nil
			}
		}

		blocks = append(blocks, block)
		return nil
	}

	for scanner.Scan() {
		line := scanner.Text()
		if strings.HasPrefix(line, "\t") {
			if cur == nil {
				return nil, fmt.Errorf("unexpected content line without header: %q", line)
			}
			cur.LineText = strings.TrimPrefix(line, "\t")
			cur.ContentSeen = true
			if err := flush(); err != nil {
				return nil, err
			}
			cur = nil
			continue
		}

		if strings.TrimSpace(line) == "" {
			continue
		}

		fields := strings.Fields(line)
		if len(fields) >= 3 && isHexCommitHash(fields[0]) {
			if err := flush(); err != nil {
				return nil, err
			}

			endLine, err := strconv.Atoi(fields[2])
			if err != nil {
				return nil, fmt.Errorf("invalid blame line number %q: %w", fields[2], err)
			}

			cur = &whyBlameHeader{
				Hash:    fields[0],
				EndLine: endLine,
				Meta: whyCommitInfo{
					Hash:      fields[0],
					ShortHash: shortCommitHash(fields[0]),
				},
			}
			continue
		}

		if cur == nil {
			return nil, fmt.Errorf("unexpected blame metadata without header: %q", line)
		}

		if strings.HasPrefix(line, "author ") {
			cur.Meta.Author = strings.TrimPrefix(line, "author ")
			continue
		}
		if strings.HasPrefix(line, "summary ") {
			cur.Meta.Subject = strings.TrimPrefix(line, "summary ")
			continue
		}
	}

	if err := scanner.Err(); err != nil {
		return nil, err
	}
	if cur != nil {
		if !cur.ContentSeen {
			return nil, fmt.Errorf("truncated blame record for commit %s at line %d", cur.Hash, cur.EndLine)
		}
		if err := flush(); err != nil {
			return nil, err
		}
	}

	return blocks, nil
}

type whyBlameHeader struct {
	Hash        string
	EndLine     int
	Meta        whyCommitInfo
	LineText    string
	ContentSeen bool
}

func shortCommitHash(hash string) string {
	if len(hash) <= 10 {
		return hash
	}
	return hash[:10]
}

func isHexCommitHash(hash string) bool {
	if len(hash) == 0 {
		return false
	}
	for _, r := range hash {
		switch {
		case r >= '0' && r <= '9':
		case r >= 'a' && r <= 'f':
		case r >= 'A' && r <= 'F':
		default:
			return false
		}
	}
	return true
}

package cli

import (
	"fmt"
	"strings"
)

func renderWhyCheckpointDetail(detail whyCheckpointDetail) string {
	var sb strings.Builder

	if detail.Entire.CheckpointID != "" {
		fmt.Fprintf(&sb, "Checkpoint: %s\n", detail.Entire.CheckpointID)
	}
	if detail.Entire.Agent != "" {
		fmt.Fprintf(&sb, "Agent: %s\n", detail.Entire.Agent)
	}
	if detail.Entire.Summary != "" {
		if detail.Entire.IsFallback {
			fmt.Fprintf(&sb, "Fallback Summary: %s\n", detail.Entire.Summary)
		} else {
			fmt.Fprintf(&sb, "Generated Summary: %s\n", detail.Entire.Summary)
		}
	}

	hash := detail.Commit.Hash
	if hash == "" {
		hash = detail.Commit.ShortHash
	}
	if hash != "" {
		fmt.Fprintf(&sb, "Commit: %s\n", hash)
	}
	if detail.Commit.Author != "" {
		fmt.Fprintf(&sb, "Author: %s\n", detail.Commit.Author)
	}
	if detail.Commit.WhenText != "" {
		fmt.Fprintf(&sb, "When: %s\n", detail.Commit.WhenText)
	}
	if detail.Commit.Subject != "" {
		fmt.Fprintf(&sb, "Subject: %s\n", detail.Commit.Subject)
	}

	return sb.String()
}

func renderWhyCommitDetail(detail whyCommitDetail) string {
	var sb strings.Builder

	hash := detail.Commit.Hash
	if hash == "" {
		hash = detail.Commit.ShortHash
	}

	if hash != "" {
		fmt.Fprintf(&sb, "Commit: %s\n", hash)
	}
	if detail.Commit.Author != "" {
		fmt.Fprintf(&sb, "Author: %s\n", detail.Commit.Author)
	}
	if detail.Commit.WhenText != "" {
		fmt.Fprintf(&sb, "When: %s\n", detail.Commit.WhenText)
	}
	if detail.Commit.Subject != "" {
		fmt.Fprintf(&sb, "Subject: %s\n", detail.Commit.Subject)
	}
	if detail.Diff != "" {
		sb.WriteString("Diff:\n")
		sb.WriteString(detail.Diff)
		if !strings.HasSuffix(detail.Diff, "\n") {
			sb.WriteString("\n")
		}
	}

	return sb.String()
}

func renderWhyStatic(blocks []whyBlock) string {
	var sb strings.Builder

	for i, block := range blocks {
		if i > 0 {
			sb.WriteString("\n")
		}

		fmt.Fprintf(&sb, "Lines %s\n", block.RangeText())

		if block.Commit.ShortHash != "" {
			fmt.Fprintf(&sb, "Commit: %s\n", block.Commit.ShortHash)
		}
		if block.Commit.Author != "" {
			fmt.Fprintf(&sb, "Author: %s\n", block.Commit.Author)
		}
		if block.Commit.WhenText != "" {
			fmt.Fprintf(&sb, "When: %s\n", block.Commit.WhenText)
		}
		if block.Commit.Subject != "" {
			fmt.Fprintf(&sb, "Subject: %s\n", block.Commit.Subject)
		}

		if block.Entire != nil {
			if block.Entire.CheckpointID != "" {
				fmt.Fprintf(&sb, "Entire Checkpoint: %s\n", block.Entire.CheckpointID)
			}
			if block.Entire.Agent != "" {
				fmt.Fprintf(&sb, "Entire Agent: %s\n", block.Entire.Agent)
			}
			if block.Entire.Summary != "" {
				fmt.Fprintf(&sb, "Entire Summary: %s\n", block.Entire.Summary)
			}
		}

		if len(block.CodeLines) > 0 {
			sb.WriteString("Code:\n")
			for _, line := range block.CodeLines {
				fmt.Fprintf(&sb, "  %s\n", line)
			}
		}
	}

	return sb.String()
}

package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os/exec"
	"strings"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/trailers"

	"github.com/go-git/go-git/v6"
	"github.com/spf13/cobra"
)

var errWhyOptionalCheckpointMetadata = errors.New("why optional checkpoint metadata unavailable")

var lookupWhyCommitInfo = func(ctx context.Context, hash string) (whyCommitInfo, *git.Repository, id.CheckpointID, error) {
	repo, err := openRepository(ctx)
	if err != nil {
		return whyCommitInfo{}, nil, id.EmptyCheckpointID, err
	}

	resolvedHash, err := resolveCommitUnambiguous(repo, hash)
	if err != nil {
		return whyCommitInfo{}, nil, id.EmptyCheckpointID, err
	}

	commit, err := repo.CommitObject(resolvedHash)
	if err != nil {
		return whyCommitInfo{}, nil, id.EmptyCheckpointID, err
	}

	info := whyCommitInfo{
		Hash:      resolvedHash.String(),
		ShortHash: shortCommitHash(resolvedHash.String()),
		Author:    commit.Author.Name,
		Email:     commit.Author.Email,
		WhenText:  commit.Author.When.Local().Format("2006-01-02 15:04:05"),
		Subject:   commitSubject(commit.Message),
	}

	checkpointID, hasCheckpoint := trailers.ParseCheckpoint(commit.Message)
	if !hasCheckpoint {
		return info, repo, id.EmptyCheckpointID, nil
	}

	return info, repo, checkpointID, nil
}

func enrichWhyBlocks(ctx context.Context, blocks []whyBlock) ([]whyBlock, error) {
	if len(blocks) == 0 {
		return nil, nil
	}

	uniqueHashes := make([]string, 0, len(blocks))
	seen := make(map[string]struct{}, len(blocks))
	for _, block := range blocks {
		if block.Commit.Hash == "" {
			continue
		}
		if _, ok := seen[block.Commit.Hash]; ok {
			continue
		}
		seen[block.Commit.Hash] = struct{}{}
		uniqueHashes = append(uniqueHashes, block.Commit.Hash)
	}

	resolved := make(map[string]struct {
		commit whyCommitInfo
		entire *whyEntireInfo
	}, len(uniqueHashes))
	for _, hash := range uniqueHashes {
		commit, entire, err := resolveWhyCommitMetadata(ctx, hash)
		if err != nil {
			if errors.Is(err, errWhyOptionalCheckpointMetadata) {
				resolved[hash] = struct {
					commit whyCommitInfo
					entire *whyEntireInfo
				}{commit: commit, entire: nil}
				continue
			}
			return nil, err
		}
		resolved[hash] = struct {
			commit whyCommitInfo
			entire *whyEntireInfo
		}{commit: commit, entire: entire}
	}

	out := make([]whyBlock, len(blocks))
	copy(out, blocks)
	for i := range out {
		block := out[i]
		if block.Commit.Hash == "" {
			continue
		}
		resolution, ok := resolved[block.Commit.Hash]
		if !ok {
			continue
		}
		out[i].Commit = resolution.commit
		if resolution.entire != nil {
			out[i].Entire = resolution.entire
		}
	}

	return out, nil
}

var loadWhyDisplayData = loadWhyDisplayDataImpl

var writeWhyStaticOutput = func(w io.Writer, content string) error {
	_, err := fmt.Fprint(w, content)
	return err
}

var shouldRunWhyTUI = func(w io.Writer) bool {
	return !IsAccessibleMode() && isTerminalWriter(w)
}

var runWhyTUI = func(ctx context.Context, w io.Writer, path string, blocks []whyBlock) error {
	styles := newStatusStyles(w)
	model := newWhyModel(ctx, path, blocks, styles)
	p := tea.NewProgram(model, tea.WithAltScreen())
	_, err := p.Run()
	return err
}

func loadWhyDisplayDataImpl(ctx context.Context, path string) ([]whyBlock, error) {
	blocks, err := loadWhyBlocks(ctx, path)
	if err != nil {
		return nil, err
	}
	enriched, err := enrichWhyBlocks(ctx, blocks)
	if err != nil {
		return nil, err
	}
	for i := range enriched {
		if enriched[i].Detail != "" {
			continue
		}
		if enriched[i].Entire != nil {
			enriched[i].Detail = whyDetailCheckpoint
			continue
		}
		enriched[i].Detail = whyDetailCommit
	}
	return enriched, nil
}

var resolveWhyCommitMetadata = func(ctx context.Context, hash string) (whyCommitInfo, *whyEntireInfo, error) {
	info, repo, checkpointID, err := lookupWhyCommitInfo(ctx, hash)
	if err != nil {
		return whyCommitInfo{}, nil, err
	}
	if checkpointID.IsEmpty() {
		return info, nil, nil
	}

	entire, err := lookupWhyCheckpointInfo(ctx, repo, checkpointID, info.Subject)
	if err != nil {
		return info, nil, err
	}

	return info, entire, nil
}

var lookupWhyCheckpointInfo = func(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID, commitSubject string) (*whyEntireInfo, error) {
	if repo == nil {
		var err error
		repo, err = openRepository(ctx)
		if err != nil {
			return nil, err
		}
	}

	v1Store := checkpoint.NewGitStore(repo)
	v2Store := checkpoint.NewV2GitStore(repo, "origin")

	reader, summary, err := checkpoint.ResolveCommittedReaderForCheckpoint(ctx, checkpointID, v1Store, v2Store, true)
	if err != nil {
		if errors.Is(err, checkpoint.ErrCheckpointNotFound) {
			return nil, fmt.Errorf("%w: %w", errWhyOptionalCheckpointMetadata, err)
		}
		return nil, err
	}

	return loadWhyEntireInfo(ctx, reader, summary, checkpointID, commitSubject)
}

var loadWhyEntireInfo = loadWhyEntireInfoImpl

func loadWhyEntireInfoImpl(ctx context.Context, reader checkpoint.CommittedReader, summary *checkpoint.CheckpointSummary, checkpointID id.CheckpointID, commitSubject string) (*whyEntireInfo, error) {
	if summary == nil {
		return nil, nil
	}

	sessionIndex := len(summary.Sessions) - 1
	if sessionIndex < 0 {
		return &whyEntireInfo{
			CheckpointID: checkpointID.String(),
			Summary:      commitSubject,
			IsFallback:   true,
		}, nil
	}

	sessionMetadata, err := readWhySessionMetadata(ctx, reader, checkpointID, sessionIndex)
	if err != nil {
		return nil, err
	}
	if sessionMetadata == nil {
		return &whyEntireInfo{
			CheckpointID: checkpointID.String(),
			Summary:      commitSubject,
			IsFallback:   true,
		}, nil
	}

	summaryText, isFallback := selectWhySummary(sessionMetadata.Summary, commitSubject)
	return &whyEntireInfo{
		CheckpointID: checkpointID.String(),
		Agent:        string(sessionMetadata.Agent),
		Summary:      summaryText,
		IsFallback:   isFallback,
	}, nil
}

var readWhySessionMetadata = func(ctx context.Context, reader checkpoint.CommittedReader, checkpointID id.CheckpointID, sessionIndex int) (*checkpoint.CommittedMetadata, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}

	switch r := reader.(type) {
	case interface {
		ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*checkpoint.CommittedMetadata, error)
	}:
		return r.ReadSessionMetadata(ctx, checkpointID, sessionIndex)
	case interface {
		ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*checkpoint.SessionContent, error)
	}:
		content, err := r.ReadSessionMetadataAndPrompts(ctx, checkpointID, sessionIndex)
		if err != nil {
			return nil, err
		}
		if content == nil {
			return nil, nil
		}
		return &content.Metadata, nil
	default:
		return nil, fmt.Errorf("reader does not support metadata-only session reads")
	}
}

func selectWhySummary(summary *checkpoint.Summary, commitSubject string) (string, bool) {
	if summary != nil {
		if text := strings.TrimSpace(summary.Outcome); text != "" {
			return text, false
		}
		if text := strings.TrimSpace(summary.Intent); text != "" {
			return text, true
		}
	}

	if text := strings.TrimSpace(commitSubject); text != "" {
		return text, true
	}

	return "", true
}

func commitSubject(message string) string {
	subject, _, found := strings.Cut(message, "\n")
	if found {
		return strings.TrimSpace(subject)
	}
	return strings.TrimSpace(message)
}

var loadWhyCommitDiff = loadWhyCommitDiffImpl

func loadWhyCommitDiffImpl(ctx context.Context, path, commitHash string) (string, error) {
	if strings.TrimSpace(commitHash) == "" {
		return "", nil
	}

	repoRoot, targetPath, err := resolveWhyBlameTargetPath(ctx, path)
	if err != nil {
		return "", err
	}

	return runGitShowWhyCommitDiff(ctx, repoRoot, commitHash, targetPath)
}

var runGitShowWhyCommitDiff = func(ctx context.Context, repoRoot, commitHash, path string) (string, error) {
	cmd := exec.CommandContext(ctx, "git", "show", "--format=", "--no-ext-diff", commitHash, "--", path)
	cmd.Dir = repoRoot

	output, err := cmd.CombinedOutput()
	if err != nil {
		return "", fmt.Errorf("git show %s -- %s: %w: %s", commitHash, path, err, strings.TrimSpace(string(output)))
	}

	return string(output), nil
}

func newWhyCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "why <path>",
