package cli

import (
	"context"
	"fmt"
	"path/filepath"
	"strings"

	"github.com/alecthomas/chroma/v2/formatters"
	"github.com/alecthomas/chroma/v2/lexers"
	"github.com/alecthomas/chroma/v2/quick"
	"github.com/alecthomas/chroma/v2/styles"
	"github.com/charmbracelet/bubbles/viewport"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
)

type whyMode int

const (
	whyModeBrowse whyMode = iota
	whyModeDetail
)

type whyStyles struct {
	statusStyles

	sectionTitle lipgloss.Style
	selected     lipgloss.Style
	label        lipgloss.Style
	helpKey      lipgloss.Style
	helpSep      lipgloss.Style
	panelBorder  lipgloss.Style
	codeBorder   lipgloss.Style
}

func newWhyStyles(ss statusStyles) whyStyles {
	s := whyStyles{statusStyles: ss}
	if !ss.colorEnabled {
		return s
	}

	s.sectionTitle = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("244"))
	s.selected = lipgloss.NewStyle().Foreground(lipgloss.Color("214")).Bold(true)
	s.label = lipgloss.NewStyle().Foreground(lipgloss.Color("244"))
	s.helpKey = lipgloss.NewStyle().Foreground(lipgloss.Color("245"))
	s.helpSep = lipgloss.NewStyle().Foreground(lipgloss.Color("240"))
	s.panelBorder = lipgloss.NewStyle().
		Border(lipgloss.RoundedBorder()).
		BorderForeground(lipgloss.Color("243")).
		Padding(0, 1)
	s.codeBorder = lipgloss.NewStyle().
		Border(lipgloss.RoundedBorder()).
		BorderForeground(lipgloss.Color("240")).
		Padding(0, 1)

	return s
}

type whyModel struct {
	ctx    context.Context
	path   string
	blocks []whyBlock

	cursor int
	width  int
	height int
	mode   whyMode

	styles   whyStyles
	browseVP viewport.Model
	detailVP viewport.Model
}

func newWhyModel(ctx context.Context, path string, blocks []whyBlock, ss statusStyles) whyModel {
	m := whyModel{
		ctx:      ctx,
		path:     path,
		blocks:   blocks,
		width:    ss.width,
		mode:     whyModeBrowse,
		styles:   newWhyStyles(ss),
		browseVP: viewport.New(ss.width, 1),
	}
	return m.refreshBrowseContent()
}

func (m whyModel) Init() tea.Cmd {
	return nil
}

func (m whyModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) { //nolint:ireturn,cyclop // bubbletea interface
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.browseVP.Width = msg.Width
		m.browseVP.Height = max(msg.Height-1, 1)
		if m.mode == whyModeDetail {
			m.detailVP.Width = msg.Width
			m.detailVP.Height = max(msg.Height-2, 1)
		}
		m = m.refreshBrowseContent()
		return m, nil
	case tea.KeyMsg:
		switch m.mode {
		case whyModeDetail:
			return m.updateDetailMode(msg)
		default:
			return m.updateBrowseMode(msg)
		}
	}

	return m, nil
}

func (m whyModel) updateBrowseMode(msg tea.KeyMsg) (tea.Model, tea.Cmd) { //nolint:ireturn // bubbletea pattern
	switch msg.String() {
	case "q", "ctrl+c":
		return m, tea.Quit
	case "up", "k":
		if m.cursor > 0 {
			m.cursor--
			m = m.refreshBrowseContent()
		}
	case "down", "j":
		if m.cursor < len(m.blocks)-1 {
			m.cursor++
			m = m.refreshBrowseContent()
		}
	case "enter", " ":
		if block := m.selectedBlock(); block != nil {
			m.mode = whyModeDetail
			m.detailVP = viewport.New(m.width, max(m.height-2, 1))
			m.detailVP.SetContent(m.renderDetailContent(*block))
			return m, nil
		}
	default:
		var cmd tea.Cmd
		m.browseVP, cmd = m.browseVP.Update(msg)
		return m, cmd
	}

	return m, nil
}

func (m whyModel) updateDetailMode(msg tea.KeyMsg) (tea.Model, tea.Cmd) { //nolint:ireturn // bubbletea pattern
	switch msg.String() {
	case "esc", "backspace":
		m.mode = whyModeBrowse
		return m, nil
	case "q", "ctrl+c":
		return m, tea.Quit
	}

	var cmd tea.Cmd
	m.detailVP, cmd = m.detailVP.Update(msg)
	return m, cmd
}

func (m whyModel) View() string {
	if m.width == 0 {
		return ""
	}

	if m.mode == whyModeDetail {
		return m.viewDetail()
	}

	return m.browseVP.View() + "\n" + m.viewHelp()
}

func (m whyModel) refreshBrowseContent() whyModel {
	m.browseVP.SetContent(m.renderBrowseContent())
	return m
}

func (m whyModel) selectedBlock() *whyBlock {
	if m.cursor < 0 || m.cursor >= len(m.blocks) {
		return nil
	}
	return &m.blocks[m.cursor]
}

func (m whyModel) renderBrowseContent() string {
	var b strings.Builder
	leftWidth, rightWidth := m.browsePanelWidths()

	header := fmt.Sprintf("%s\n\n%s", m.styles.render(m.styles.sectionTitle, "ENTIRE WHY"), m.path)
	b.WriteString(header)
	b.WriteString("\n\n")

	if len(m.blocks) == 0 {
		b.WriteString(m.styles.render(m.styles.dim, "No blamed blocks found."))
		return b.String()
	}

	listPanel := m.styles.panelBorder.Width(leftWidth).Render(m.renderBlockList(leftWidth - 2))
	codePanel := m.styles.codeBorder.Width(rightWidth).Render(m.renderCodePane(rightWidth - 2))
	b.WriteString(lipgloss.JoinHorizontal(lipgloss.Top, listPanel, " ", codePanel))

	return strings.TrimRight(b.String(), "\n")
}

func (m whyModel) browsePanelWidths() (int, int) {
	contentWidth := max(m.width, 40)
	left := contentWidth / 2
	if left < 28 {
		left = 28
	}
	right := contentWidth - left - 1
	if right < 20 {
		right = 20
		left = max(contentWidth-right-1, 20)
	}
	return left, right
}

func (m whyModel) renderBlockList(width int) string {
	var b strings.Builder
	b.WriteString(m.styles.render(m.styles.sectionTitle, "BLOCKS"))
	b.WriteString("\n\n")

	for i, block := range m.blocks {
		row := renderWhyBlockRow(block, width)
		if i == m.cursor && m.styles.colorEnabled {
			row = m.styles.selected.Render(row)
		}
		if i == m.cursor && !m.styles.colorEnabled {
			row = "> " + row
		}
		b.WriteString(row)
		if i < len(m.blocks)-1 {
			b.WriteString("\n\n")
		}
	}

	return b.String()
}

func renderWhyBlockRow(block whyBlock, width int) string {
	var lines []string

	head := strings.TrimSpace(strings.Join([]string{
		block.RangeText(),
		shortWhyBlockCommit(block.Commit),
		block.Commit.Author,
	}, "  "))
	lines = append(lines, truncateWhyText(head, width))

	if block.Entire != nil {
		entireLine := strings.TrimSpace(strings.Join([]string{
			block.Entire.CheckpointID,
			block.Entire.Agent,
		}, "  "))
		if entireLine != "" {
			lines = append(lines, truncateWhyText(entireLine, width))
		}
		if block.Entire.Summary != "" {
			lines = append(lines, truncateWhyText(block.Entire.Summary, width))
		}
	} else if block.Commit.Subject != "" {
		lines = append(lines, truncateWhyText(block.Commit.Subject, width))
	}

	return strings.Join(lines, "\n")
}

func shortWhyBlockCommit(commit whyCommitInfo) string {
	if commit.ShortHash != "" {
		return commit.ShortHash
	}
	return commit.Hash
}

func truncateWhyText(value string, width int) string {
	if width <= 0 {
		return value
	}

	runes := []rune(value)
	if len(runes) <= width {
		return value
	}
	if width == 1 {
		return string(runes[:1])
	}
	return string(runes[:width-1]) + "…"
}

func (m whyModel) renderCodePane(width int) string {
	var b strings.Builder
	b.WriteString(m.styles.render(m.styles.sectionTitle, "CODE"))
	b.WriteString("\n\n")

	block := m.selectedBlock()
	if block == nil {
		b.WriteString(m.styles.render(m.styles.dim, "No block selected."))
		return b.String()
	}

	title := fmt.Sprintf("Lines %s", block.RangeText())
	if block.Commit.Subject != "" {
		title += "  " + block.Commit.Subject
	}
	b.WriteString(truncateWhyText(title, width))
	b.WriteString("\n\n")

	code := strings.Join(block.CodeLines, "\n")
	if code == "" {
		b.WriteString(m.styles.render(m.styles.dim, "No source available."))
		return b.String()
	}

	b.WriteString(renderWhyHighlightedCode(m.path, code))
	return strings.TrimRight(b.String(), "\n")
}

func renderWhyHighlightedCode(path, code string) string {
	if strings.TrimSpace(code) == "" {
		return code
	}

	styleName := "dracula"
	if styles.Get(styleName) == nil {
		styleName = "monokai"
	}

	formatter := "terminal256"
	if formatters.Get(formatter) == nil {
		return code
	}

	lexer := lexers.Match(path)
	if lexer == nil {
		lexer = lexers.Match(filepath.Base(path))
	}
	if lexer == nil {
		lexer = lexers.Analyse(code)
	}
	if lexer == nil {
		return code
	}

	var b strings.Builder
	if err := quick.Highlight(&b, code, lexer.Config().Name, formatter, styleName); err != nil {
		return code
	}

	return strings.TrimRight(b.String(), "\n")
}

func (m whyModel) renderDetailContent(block whyBlock) string {
	switch whyBlockDetailKind(block) {
	case whyDetailCheckpoint:
		return renderWhyCheckpointDetail(whyCheckpointDetail{
			Commit: block.Commit,
