func initWhyTestModel() whyModel {
	ss := statusStyles{colorEnabled: false, width: 100}
	m := newWhyModel(context.Background(), "cmd/entire/main.go", testWhyBlocks(), ss)
	m.height = 40
	m.browseVP.Height = 39
	m = m.refreshBrowseContent()
	return m
}

func updateWhyModel(t *testing.T, m whyModel, msg tea.Msg) whyModel {
	t.Helper()
	updated, _ := m.Update(msg)
	result, ok := updated.(whyModel)
	if !ok {
		t.Fatalf("Update returned %T, want whyModel", updated)
	}
	return result
}

func TestWhyModel_NavigationAndDetailMode(t *testing.T) {
	t.Parallel()

	m := initWhyTestModel()
	if m.cursor != 0 {
		t.Fatalf("initial cursor = %d, want 0", m.cursor)
	}

	m = updateWhyModel(t, m, tea.KeyMsg{Type: tea.KeyDown})
	if m.cursor != 1 {
		t.Fatalf("after down: cursor = %d, want 1", m.cursor)
	}

	m = updateWhyModel(t, m, tea.KeyMsg{Type: tea.KeyEnter})
	if m.mode != whyModeDetail {
		t.Fatalf("after enter: mode = %d, want detail", m.mode)
	}
	if !strings.Contains(m.detailVP.View(), "Commit: 7f93a963e3222222222222222222222222222222") {
		t.Fatalf("detail view missing commit detail:\n%s", m.detailVP.View())
	}

	m = updateWhyModel(t, m, tea.KeyMsg{Type: tea.KeyEsc})
	if m.mode != whyModeBrowse {
		t.Fatalf("after esc: mode = %d, want browse", m.mode)
	}
}

