func TestWhyCommand_UsesTUIWhenInteractive(t *testing.T) {
	origLoad := loadWhyDisplayData
	origShouldRunTUI := shouldRunWhyTUI
	origRunWhyTUI := runWhyTUI
	origWriteWhyStaticOutput := writeWhyStaticOutput
	t.Cleanup(func() {
		loadWhyDisplayData = origLoad
		shouldRunWhyTUI = origShouldRunTUI
		runWhyTUI = origRunWhyTUI
		writeWhyStaticOutput = origWriteWhyStaticOutput
	})

	loadWhyDisplayData = func(_ context.Context, path string) ([]whyBlock, error) {
