			t.Fatalf("path = %q, want %q", path, "cmd/entire/main.go")
		}
		if len(blocks) != 2 {
			t.Fatalf("blocks = %d, want 2", len(blocks))
		}
		return nil
	}
	writeWhyStaticOutput = func(io.Writer, string) error {
