	cmd := newWhyCmd()
	cmd.SetArgs([]string{"cmd/entire/main.go"})
	var out bytes.Buffer
	cmd.SetOut(&out)

	if err := cmd.ExecuteContext(context.Background()); err != nil {
		t.Fatalf("command error: %v", err)
	}
	if !tuiCalled {
		t.Fatal("expected TUI path to be used")
	}
}

