package cli

import (
	"fmt"
	"strings"
)

const (
	whyCommitWidth     = 10
	whyAuthorWidth     = 18
	whyCheckpointWidth = 12
	whyAgentWidth      = 12
	whyLineWidth       = 4
)

func renderWhyCheckpointDetail(detail whyCheckpointDetail) string {
	var sb strings.Builder

	if detail.Entire.CheckpointID != "" {
		fmt.Fprintf(&sb, "Checkpoint: %s\n", detail.Entire.CheckpointID)
	}
	if detail.Entire.Agent != "" {
		fmt.Fprintf(&sb, "Agent: %s\n", detail.Entire.Agent)
	}
	if detail.Entire.Summary != "" {
		if detail.Entire.IsFallback {
			fmt.Fprintf(&sb, "Fallback Summary: %s\n", detail.Entire.Summary)
		} else {
			fmt.Fprintf(&sb, "Generated Summary: %s\n", detail.Entire.Summary)
		}
	}

	hash := detail.Commit.Hash
	if hash == "" {
		hash = detail.Commit.ShortHash
	}
	if hash != "" {
		fmt.Fprintf(&sb, "Commit: %s\n", hash)
	}
	if detail.Commit.Author != "" {
		fmt.Fprintf(&sb, "Author: %s\n", detail.Commit.Author)
	}
	if detail.Commit.WhenText != "" {
		fmt.Fprintf(&sb, "When: %s\n", detail.Commit.WhenText)
	}
	if detail.Commit.Subject != "" {
		fmt.Fprintf(&sb, "Subject: %s\n", detail.Commit.Subject)
	}
	if detail.Diff != "" {
		sb.WriteString("Diff:\n")
		sb.WriteString(renderWhyHighlightedDiff(detail.Diff))
		if !strings.HasSuffix(detail.Diff, "\n") {
			sb.WriteString("\n")
		}
	}

	return sb.String()
}

func renderWhyCommitDetail(detail whyCommitDetail) string {
	var sb strings.Builder

	hash := detail.Commit.Hash
	if hash == "" {
		hash = detail.Commit.ShortHash
	}

	if hash != "" {
		fmt.Fprintf(&sb, "Commit: %s\n", hash)
	}
	if detail.Commit.Author != "" {
		fmt.Fprintf(&sb, "Author: %s\n", detail.Commit.Author)
	}
	if detail.Commit.WhenText != "" {
		fmt.Fprintf(&sb, "When: %s\n", detail.Commit.WhenText)
	}
	if detail.Commit.Subject != "" {
		fmt.Fprintf(&sb, "Subject: %s\n", detail.Commit.Subject)
	}
	if detail.Diff != "" {
		sb.WriteString("Diff:\n")
		sb.WriteString(renderWhyHighlightedDiff(detail.Diff))
		if !strings.HasSuffix(detail.Diff, "\n") {
			sb.WriteString("\n")
		}
	}

	return sb.String()
}

func renderWhyStatic(blocks []whyBlock) string {
	var sb strings.Builder
	rows := flattenWhyRows(blocks)

	if len(rows) == 0 {
		return ""
	}

	sb.WriteString(renderWhyStaticHeader())
	sb.WriteString("\n")

	for i, row := range rows {
		if i > 0 {
			sb.WriteString("\n")
		}
		fmt.Fprintf(&sb, "%s | %s", renderWhyRowGutter(row), row.CodeLine)
	}

	return sb.String()
}

func renderWhyStaticHeader() string {
	return strings.Join([]string{
		padWhyField("COMMIT", whyCommitWidth),
		padWhyField("AUTHOR", whyAuthorWidth),
		padWhyField("CHECKPOINT", whyCheckpointWidth),
		padWhyField("AGENT", whyAgentWidth),
		padWhyField("LINE", whyLineWidth),
	}, " ") + " | CODE"
}

func renderWhyRowGutter(row whyRow) string {
	return strings.Join([]string{
		padWhyField(whyRowCommitHash(row), whyCommitWidth),
		padWhyField(row.Commit.Author, whyAuthorWidth),
		padWhyField(whyRowCheckpointID(row), whyCheckpointWidth),
		padWhyField(whyRowAgent(row), whyAgentWidth),
		padWhyField(itoa(row.LineNumber), whyLineWidth),
	}, " ")
}

func whyRowCommitHash(row whyRow) string {
	if row.Commit.ShortHash != "" {
		return row.Commit.ShortHash
	}
	return row.Commit.Hash
}

func whyRowCheckpointID(row whyRow) string {
	if row.Entire == nil || row.Entire.CheckpointID == "" {
		return "-"
	}
	return row.Entire.CheckpointID
}

func whyRowAgent(row whyRow) string {
	if row.Entire == nil || row.Entire.Agent == "" {
		return "-"
	}
	return row.Entire.Agent
}

func padWhyField(value string, width int) string {
	value = truncateWhyDisplayField(value, width)
	if len([]rune(value)) >= width {
		return value
	}
	return value + strings.Repeat(" ", width-len([]rune(value)))
}

func truncateWhyDisplayField(value string, width int) string {
	if width <= 0 {
		return value
	}

	runes := []rune(value)
	if len(runes) <= width {
		return value
	}
	if width == 1 {
		return string(runes[:1])
	}
	return string(runes[:width-1]) + "…"
}

func renderWhyHighlightedDiff(diff string) string {
	if strings.TrimSpace(diff) == "" {
		return diff
	}
	return renderWhyHighlightedCode("why.diff", diff)
}

func renderWhyInteractiveGutter(row whyRow) string {
	return strings.Join([]string{
		padWhyField(whyRowCommitHash(row), whyCommitWidth),
		padWhyField(row.Commit.Author, whyAuthorWidth),
		padWhyField(itoa(row.LineNumber), whyLineWidth),
	}, " ")
}

func renderWhyInteractiveHeader() string {
	return strings.Join([]string{
		padWhyField("COMMIT", whyCommitWidth),
		padWhyField("AUTHOR", whyAuthorWidth),
		padWhyField("LINE", whyLineWidth),
	}, " ") + " | CODE"
}

package cli

import (
	"context"
	"fmt"
	"path/filepath"
	"strings"

	"github.com/alecthomas/chroma/v2/formatters"
	"github.com/alecthomas/chroma/v2/lexers"
	"github.com/alecthomas/chroma/v2/quick"
	"github.com/alecthomas/chroma/v2/styles"
	"github.com/charmbracelet/bubbles/viewport"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
)

type whyMode int

const (
	whyModeBrowse whyMode = iota
	whyModeDetail
)

type whyStyles struct {
	statusStyles

	sectionTitle lipgloss.Style
	selected     lipgloss.Style
	label        lipgloss.Style
	helpKey      lipgloss.Style
	helpSep      lipgloss.Style
	panelBorder  lipgloss.Style
	codeBorder   lipgloss.Style
}

func newWhyStyles(ss statusStyles) whyStyles {
	s := whyStyles{statusStyles: ss}
	if !ss.colorEnabled {
		return s
	}

	s.sectionTitle = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("244"))
	s.selected = lipgloss.NewStyle().Foreground(lipgloss.Color("214")).Bold(true)
	s.label = lipgloss.NewStyle().Foreground(lipgloss.Color("244"))
	s.helpKey = lipgloss.NewStyle().Foreground(lipgloss.Color("245"))
	s.helpSep = lipgloss.NewStyle().Foreground(lipgloss.Color("240"))
	s.panelBorder = lipgloss.NewStyle().
		Border(lipgloss.RoundedBorder()).
		BorderForeground(lipgloss.Color("243")).
		Padding(0, 1)
	s.codeBorder = lipgloss.NewStyle().
		Border(lipgloss.RoundedBorder()).
		BorderForeground(lipgloss.Color("240")).
		Padding(0, 1)

	return s
}

type whyModel struct {
	ctx    context.Context
	path   string
	blocks []whyBlock
	rows   []whyRow

	cursor int
	width  int
	height int
	mode   whyMode

	styles   whyStyles
	browseVP viewport.Model
	detailVP viewport.Model
}

func newWhyModel(ctx context.Context, path string, blocks []whyBlock, ss statusStyles) whyModel {
	m := whyModel{
		ctx:      ctx,
		path:     path,
		blocks:   blocks,
		rows:     flattenWhyRows(blocks),
		width:    ss.width,
		mode:     whyModeBrowse,
		styles:   newWhyStyles(ss),
		browseVP: viewport.New(ss.width, 1),
	}
	return m.refreshBrowseContent()
}

func (m whyModel) Init() tea.Cmd {
	return nil
}

func (m whyModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) { //nolint:ireturn,cyclop // bubbletea interface
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.browseVP.Width = msg.Width
		m.browseVP.Height = max(msg.Height-4, 1)
		if m.mode == whyModeDetail {
			m.detailVP.Width = msg.Width
			m.detailVP.Height = max(msg.Height-3, 1)
		}
		m = m.refreshBrowseContent()
		return m, nil
	case tea.KeyMsg:
		switch m.mode {
		case whyModeDetail:
			return m.updateDetailMode(msg)
		default:
			return m.updateBrowseMode(msg)
		}
	}

	return m, nil
}

func (m whyModel) updateBrowseMode(msg tea.KeyMsg) (tea.Model, tea.Cmd) { //nolint:ireturn // bubbletea pattern
	switch msg.String() {
	case "q", "ctrl+c":
		return m, tea.Quit
	case "up", "k":
		if m.cursor > 0 {
			m.cursor--
			m = m.refreshBrowseContent()
		}
	case "down", "j":
		if m.cursor < len(m.rows)-1 {
			m.cursor++
			m = m.refreshBrowseContent()
		}
	case "enter", " ":
		if block := m.selectedBlock(); block != nil {
			m.mode = whyModeDetail
			m.detailVP = viewport.New(m.width, max(m.height-3, 1))
			m.detailVP.SetContent(m.renderDetailContent(*block))
			return m, nil
		}
	default:
		var cmd tea.Cmd
		m.browseVP, cmd = m.browseVP.Update(msg)
		return m, cmd
	}

	return m, nil
}

func (m whyModel) updateDetailMode(msg tea.KeyMsg) (tea.Model, tea.Cmd) { //nolint:ireturn // bubbletea pattern
	switch msg.String() {
	case "esc", "backspace":
		m.mode = whyModeBrowse
		return m, nil
	case "q", "ctrl+c":
		return m, tea.Quit
	}

	var cmd tea.Cmd
	m.detailVP, cmd = m.detailVP.Update(msg)
	return m, cmd
}

func (m whyModel) View() string {
	if m.width == 0 {
		return ""
	}

	if m.mode == whyModeDetail {
		return m.viewDetail()
	}

	return strings.Join([]string{
		m.viewBrowseHeader(),
		renderWhyInteractiveHeader(),
		m.styles.horizontalRule(max(m.width, 20)),
		m.browseVP.View(),
		m.viewHelp(),
	}, "\n")
}

func (m whyModel) refreshBrowseContent() whyModel {
	m.browseVP.SetContent(m.renderBrowseContent())
	return m.ensureBrowseCursorVisible()
}

func (m whyModel) ensureBrowseCursorVisible() whyModel {
	if m.browseVP.Height <= 0 {
		return m
	}
	if m.cursor < m.browseVP.YOffset {
		m.browseVP.YOffset = m.cursor
	}
	if m.cursor >= m.browseVP.YOffset+m.browseVP.Height {
		m.browseVP.YOffset = m.cursor - m.browseVP.Height + 1
	}
	return m
}

func (m whyModel) selectedRow() *whyRow {
	if m.cursor < 0 || m.cursor >= len(m.rows) {
		return nil
	}
	return &m.rows[m.cursor]
}

func (m whyModel) selectedBlock() *whyBlock {
	row := m.selectedRow()
	if row == nil || row.BlockIndex < 0 || row.BlockIndex >= len(m.blocks) {
		return nil
	}
	return &m.blocks[row.BlockIndex]
}

func (m whyModel) renderBrowseContent() string {
	var b strings.Builder
	if len(m.rows) == 0 {
		b.WriteString(m.styles.render(m.styles.dim, "No blamed lines found."))
		return b.String()
	}

	codeLines := highlightWhyCodeLines(m.path, m.rows)
	for i, row := range m.rows {
		line := renderWhyBrowseRow(row, codeLines[i], m.width, i == m.cursor)
		b.WriteString(line)
		if i < len(m.rows)-1 {
			b.WriteString("\n")
		}
	}

	return b.String()
}

func renderWhyBrowseRow(row whyRow, highlightedCode string, _ int, selected bool) string {
	gutter := renderWhyInteractiveGutter(row)
	line := fmt.Sprintf("%s | %s", gutter, highlightedCode)
	if selected {
		return "> " + line
	}
	return "  " + line
}

func highlightWhyCodeLines(path string, rows []whyRow) []string {
	if len(rows) == 0 {
		return nil
	}

	codeLines := make([]string, 0, len(rows))
	for _, row := range rows {
		codeLines = append(codeLines, row.CodeLine)
	}

	highlighted := renderWhyHighlightedCode(path, strings.Join(codeLines, "\n"))
	split := strings.Split(highlighted, "\n")
	if len(split) != len(codeLines) {
		return codeLines
	}
	return split
}

func (m whyModel) viewBrowseHeader() string {
	row := m.selectedRow()
	if row == nil {
		return fmt.Sprintf("%s  %s", m.styles.render(m.styles.sectionTitle, "ENTIRE WHY"), m.path)
	}

	line1 := []string{
		fmt.Sprintf("%s  %s", m.styles.render(m.styles.sectionTitle, "ENTIRE WHY"), m.path),
		fmt.Sprintf("line %d", row.LineNumber),
		fmt.Sprintf("commit %s", whyRowCommitHash(*row)),
		fmt.Sprintf("author %s", row.Commit.Author),
	}
	if row.Commit.WhenText != "" {
		line1 = append(line1, fmt.Sprintf("when %s", row.Commit.WhenText))
	}

	line2 := []string{}
	if row.Entire != nil {
		if row.Entire.CheckpointID != "" {
			line2 = append(line2, fmt.Sprintf("checkpoint %s", row.Entire.CheckpointID))
		}
		if row.Entire.Agent != "" {
			line2 = append(line2, fmt.Sprintf("agent %s", row.Entire.Agent))
		}
		if row.Entire.Summary != "" {
			if row.Entire.IsFallback {
				line2 = append(line2, fmt.Sprintf("fallback %s", row.Entire.Summary))
			} else {
				line2 = append(line2, fmt.Sprintf("summary %s", row.Entire.Summary))
			}
		}
	} else if row.Commit.Subject != "" {
		line2 = append(line2, fmt.Sprintf("subject %s", row.Commit.Subject))
	}

	lines := []string{truncateWhyDisplayField(strings.Join(line1, "  •  "), max(m.width, 20))}
	if len(line2) > 0 {
		lines = append(lines, truncateWhyDisplayField(strings.Join(line2, "  •  "), max(m.width, 20)))
	}
	return strings.Join(lines, "\n")
}

func renderWhyHighlightedCode(path, code string) string {
	if strings.TrimSpace(code) == "" {
		return code
	}

	styleName := "dracula"
	if styles.Get(styleName) == nil {
		styleName = "monokai"
	}

	formatter := "terminal256"
	if formatters.Get(formatter) == nil {
		return code
	}

	lexer := lexers.Match(path)
	if lexer == nil {
		lexer = lexers.Match(filepath.Base(path))
	}
	if lexer == nil {
		lexer = lexers.Analyse(code)
	}
	if lexer == nil {
		return code
	}

	var b strings.Builder
	if err := quick.Highlight(&b, code, lexer.Config().Name, formatter, styleName); err != nil {
		return code
	}

	return strings.TrimRight(b.String(), "\n")
}

func (m whyModel) renderDetailContent(block whyBlock) string {
	switch whyBlockDetailKind(block) {
	case whyDetailCheckpoint:
		diff, err := loadWhyCommitDiff(m.ctx, m.path, block.Commit.Hash)
		if err != nil {
			diff = fmt.Sprintf("unavailable: %v", err)
		}
		return renderWhyCheckpointDetail(whyCheckpointDetail{
			Commit: block.Commit,
			Entire: *block.Entire,
			Diff:   diff,
		})
	default:
		diff, err := loadWhyCommitDiff(m.ctx, m.path, block.Commit.Hash)
		if err != nil {
			diff = fmt.Sprintf("unavailable: %v", err)
		}
		return renderWhyCommitDetail(whyCommitDetail{
			Commit: block.Commit,
			Diff:   diff,
		})
	}
}

func whyBlockDetailKind(block whyBlock) whyDetailKind {
	if block.Detail != "" {
		return block.Detail
	}
	if block.Entire != nil {
		return whyDetailCheckpoint
	}
	return whyDetailCommit
}

func (m whyModel) viewDetail() string {
	var b strings.Builder
	block := m.selectedBlock()
	if block == nil {
		return ""
	}

	title := fmt.Sprintf("DETAIL  %s  %s", block.RangeText(), m.path)
	b.WriteString(title)
	b.WriteString("\n")
	b.WriteString(m.styles.horizontalRule(max(m.width, 20)))
	b.WriteString("\n")
	b.WriteString(m.detailVP.View())
	b.WriteString("\n")
	b.WriteString(m.viewDetailHelp())

	return b.String()
}

func (m whyModel) viewHelp() string {
	return strings.Join([]string{
		m.styles.render(m.styles.helpKey, "j/k"),
		" navigate",
		m.styles.render(m.styles.helpSep, " • "),
		m.styles.render(m.styles.helpKey, "enter"),
		" detail",
		m.styles.render(m.styles.helpSep, " • "),
		m.styles.render(m.styles.helpKey, "q"),
		" quit",
	}, "")
}

func (m whyModel) viewDetailHelp() string {
	return strings.Join([]string{
		m.styles.render(m.styles.helpKey, "esc"),
		" back",
