func renderWhyMetaLine(parts ...string) string {
	fields := make([]string, 0, len(parts)/2)
	for i := 0; i+1 < len(parts); i += 2 {
		if strings.TrimSpace(parts[i+1]) == "" {
			continue
		}
		fields = append(fields, fmt.Sprintf("%s: %s", parts[i], parts[i+1]))
	}
	return strings.Join(fields, "  |  ")
}

func renderWhyHighlightedCode(path, code string) string {
	if strings.TrimSpace(code) == "" {
		return code
	}

	styleName := "dracula"
	if styles.Get(styleName) == nil {
		styleName = "monokai"
	}

	formatter := "terminal256"
	if formatters.Get(formatter) == nil {
		return code
	}

	lexer := lexers.Match(path)
	if lexer == nil {
		lexer = lexers.Match(filepath.Base(path))
	}
	if lexer == nil {
		lexer = lexers.Analyse(code)
	}
	if lexer == nil {
		return code
	}

	var b strings.Builder
	if err := quick.Highlight(&b, code, lexer.Config().Name, formatter, styleName); err != nil {
		return code
	}

	return strings.TrimRight(b.String(), "\n")
}

func (m whyModel) renderDetailContent(block whyBlock) string {
	switch whyBlockDetailKind(block) {
	case whyDetailCheckpoint:
		if m.checkpointDetail != nil {
			return m.renderCheckpointDetail()
		}
		return "checkpoint detail unavailable"
	default:
		diff, err := loadWhyCommitDiff(m.ctx, m.path, block.Commit.Hash)
		if err != nil {
			diff = fmt.Sprintf("unavailable: %v", err)
		}
		return renderWhyCommitDetail(whyCommitDetail{
			Commit: block.Commit,
			Diff:   diff,
		})
	}
}

func (m whyModel) renderCheckpointDetail() string {
	if m.checkpointDetail == nil {
		return ""
	}

	base := renderWhyCheckpointDetail(*m.checkpointDetail)
	if len(m.checkpointDetail.Sessions) == 0 {
		return base
	}

	var sb strings.Builder
	sb.WriteString(base)
	sb.WriteString("\nSession List:\n")
	for i, session := range m.checkpointDetail.Sessions {
		prefix := "  "
		if i == m.sessionCursor {
			prefix = "> "
		}
		fmt.Fprintf(&sb, "%s[%d] %s  Agent: %s  Created: %s\n",
			prefix,
			i+1,
			session.SessionID,
			emptyWhyValue(session.Agent, "-"),
			emptyWhyValue(session.CreatedAtText, "-"),
		)
	}
	return strings.TrimRight(sb.String(), "\n")
}

