type whyMode int

const (
	whyModeBrowse whyMode = iota
	whyModeDetail
	whyModeSessionDetail
)

type whyStyles struct {
	statusStyles

	sectionTitle lipgloss.Style
	selected     lipgloss.Style
	label        lipgloss.Style
	helpKey      lipgloss.Style
	helpSep      lipgloss.Style
	panelBorder  lipgloss.Style
	codeBorder   lipgloss.Style
}

func newWhyStyles(ss statusStyles) whyStyles {
	s := whyStyles{statusStyles: ss}
	if !ss.colorEnabled {
		return s
	}

	s.sectionTitle = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("244"))
	s.selected = lipgloss.NewStyle().Foreground(lipgloss.Color("214")).Bold(true)
	s.label = lipgloss.NewStyle().Foreground(lipgloss.Color("244"))
	s.helpKey = lipgloss.NewStyle().Foreground(lipgloss.Color("245"))
	s.helpSep = lipgloss.NewStyle().Foreground(lipgloss.Color("240"))
	s.panelBorder = lipgloss.NewStyle().
		Border(lipgloss.RoundedBorder()).
		BorderForeground(lipgloss.Color("243")).
		Padding(0, 1)
	s.codeBorder = lipgloss.NewStyle().
		Border(lipgloss.RoundedBorder()).
		BorderForeground(lipgloss.Color("240")).
		Padding(0, 1)

	return s
}

type whyModel struct {
	ctx    context.Context
	path   string
	blocks []whyBlock
	rows   []whyRow

	cursor int
	width  int
	height int
	mode   whyMode

	styles           whyStyles
	browseVP         viewport.Model
	detailVP         viewport.Model
	checkpointDetail *whyCheckpointDetail
	sessionCursor    int
	sessionDetail    *whySessionDetail
}

func newWhyModel(ctx context.Context, path string, blocks []whyBlock, ss statusStyles) whyModel {
	m := whyModel{
		ctx:      ctx,
		path:     path,
		blocks:   blocks,
		rows:     flattenWhyRows(blocks),
		width:    ss.width,
		mode:     whyModeBrowse,
		styles:   newWhyStyles(ss),
		browseVP: viewport.New(ss.width, 1),
	}
	return m.refreshBrowseContent()
}

func (m whyModel) Init() tea.Cmd {
	return nil
}

func (m whyModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) { //nolint:ireturn,cyclop // bubbletea interface
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.browseVP.Width = msg.Width
		m.browseVP.Height = max(msg.Height-4, 1)
		if m.mode == whyModeDetail || m.mode == whyModeSessionDetail {
			m.detailVP.Width = msg.Width
			m.detailVP.Height = max(msg.Height-3, 1)
		}
		m = m.refreshBrowseContent()
		return m, nil
	case tea.KeyMsg:
		switch m.mode {
		case whyModeDetail:
			return m.updateDetailMode(msg)
		case whyModeSessionDetail:
			return m.updateSessionDetailMode(msg)
		default:
			return m.updateBrowseMode(msg)
		}
	}

	return m, nil
}

func (m whyModel) updateBrowseMode(msg tea.KeyMsg) (tea.Model, tea.Cmd) { //nolint:ireturn // bubbletea pattern
	switch msg.String() {
	case "q", "ctrl+c":
		return m, tea.Quit
	case "up", "k":
		if m.cursor > 0 {
			m.cursor--
			m = m.refreshBrowseContent()
		}
	case "down", "j":
		if m.cursor < len(m.rows)-1 {
			m.cursor++
			m = m.refreshBrowseContent()
		}
	case "enter", " ":
		if block := m.selectedBlock(); block != nil {
			m.mode = whyModeDetail
			m.detailVP = viewport.New(m.width, max(m.height-3, 1))
			m.sessionCursor = 0
			m.sessionDetail = nil
			if whyBlockDetailKind(*block) == whyDetailCheckpoint {
				detail, err := loadWhyCheckpointDetail(m.ctx, m.path, *block)
				if err == nil {
					m.checkpointDetail = detail
					m.detailVP.SetContent(m.renderCheckpointDetail())
					return m, nil
				}
				m.checkpointDetail = nil
				m.detailVP.SetContent(fmt.Sprintf("checkpoint detail unavailable: %v", err))
				return m, nil
			}
			m.checkpointDetail = nil
			m.detailVP.SetContent(m.renderDetailContent(*block))
			return m, nil
		}
	default:
		var cmd tea.Cmd
		m.browseVP, cmd = m.browseVP.Update(msg)
		return m, cmd
	}

	return m, nil
}

func (m whyModel) updateDetailMode(msg tea.KeyMsg) (tea.Model, tea.Cmd) { //nolint:ireturn // bubbletea pattern
	if m.checkpointDetail != nil {
		switch msg.String() {
		case "esc", "backspace":
			m.mode = whyModeBrowse
			m.checkpointDetail = nil
			m.sessionDetail = nil
			return m, nil
		case "up", "k":
			if m.sessionCursor > 0 {
				m.sessionCursor--
				m.detailVP.SetContent(m.renderCheckpointDetail())
			}
			return m, nil
		case "down", "j":
			if m.sessionCursor < len(m.checkpointDetail.Sessions)-1 {
				m.sessionCursor++
				m.detailVP.SetContent(m.renderCheckpointDetail())
			}
			return m, nil
		case "enter", " ":
			sessionDetail := loadWhySessionDetail(m.checkpointDetail, m.sessionCursor)
			if sessionDetail != nil {
				m.mode = whyModeSessionDetail
				m.sessionDetail = sessionDetail
				m.detailVP.SetContent(renderWhySessionDetail(*sessionDetail))
			}
			return m, nil
		case "q", "ctrl+c":
			return m, tea.Quit
		}
	}

	switch msg.String() {
	case "esc", "backspace":
		m.mode = whyModeBrowse
		m.checkpointDetail = nil
		m.sessionDetail = nil
		return m, nil
	case "q", "ctrl+c":
		return m, tea.Quit
	}

	var cmd tea.Cmd
	m.detailVP, cmd = m.detailVP.Update(msg)
	return m, cmd
}

func (m whyModel) updateSessionDetailMode(msg tea.KeyMsg) (tea.Model, tea.Cmd) { //nolint:ireturn // bubbletea pattern
	switch msg.String() {
	case "esc", "backspace":
		m.mode = whyModeDetail
		m.sessionDetail = nil
		m.detailVP.SetContent(m.renderCheckpointDetail())
		return m, nil
	case "q", "ctrl+c":
		return m, tea.Quit
	}

	var cmd tea.Cmd
	m.detailVP, cmd = m.detailVP.Update(msg)
	return m, cmd
}

func (m whyModel) View() string {
	if m.width == 0 {
		return ""
	}

	if m.mode == whyModeDetail {
		return m.viewDetail()
	}
	if m.mode == whyModeSessionDetail {
		return m.viewSessionDetail()
	}

	return strings.Join([]string{
		m.viewBrowseHeader(),
		renderWhyInteractiveHeader(),
		m.styles.horizontalRule(max(m.width, 20)),
		m.browseVP.View(),
		m.viewHelp(),
	}, "\n")
}

func (m whyModel) refreshBrowseContent() whyModel {
	m.browseVP.SetContent(m.renderBrowseContent())
	return m.ensureBrowseCursorVisible()
}

func (m whyModel) ensureBrowseCursorVisible() whyModel {
	if m.browseVP.Height <= 0 {
		return m
	}
	if m.cursor < m.browseVP.YOffset {
		m.browseVP.YOffset = m.cursor
	}
	if m.cursor >= m.browseVP.YOffset+m.browseVP.Height {
		m.browseVP.YOffset = m.cursor - m.browseVP.Height + 1
	}
	return m
}

func (m whyModel) selectedRow() *whyRow {
	if m.cursor < 0 || m.cursor >= len(m.rows) {
		return nil
	}
	return &m.rows[m.cursor]
}

func (m whyModel) selectedBlock() *whyBlock {
	row := m.selectedRow()
	if row == nil || row.BlockIndex < 0 || row.BlockIndex >= len(m.blocks) {
		return nil
	}
	return &m.blocks[row.BlockIndex]
}

func (m whyModel) renderBrowseContent() string {
	var b strings.Builder
	if len(m.rows) == 0 {
		b.WriteString(m.styles.render(m.styles.dim, "No blamed lines found."))
		return b.String()
	}

	codeLines := highlightWhyCodeLines(m.path, m.rows)
	for i, row := range m.rows {
		line := renderWhyBrowseRow(row, codeLines[i], m.width, i == m.cursor)
		b.WriteString(line)
		if i < len(m.rows)-1 {
			b.WriteString("\n")
		}
	}

	return b.String()
}

func renderWhyBrowseRow(row whyRow, highlightedCode string, _ int, selected bool) string {
	gutter := renderWhyInteractiveGutter(row)
	line := fmt.Sprintf("%s | %s", gutter, highlightedCode)
	if selected {
		return "> " + line
	}
	return "  " + line
}

func highlightWhyCodeLines(path string, rows []whyRow) []string {
	if len(rows) == 0 {
		return nil
	}

	codeLines := make([]string, 0, len(rows))
	for _, row := range rows {
		codeLines = append(codeLines, row.CodeLine)
	}

	highlighted := renderWhyHighlightedCode(path, strings.Join(codeLines, "\n"))
	split := strings.Split(highlighted, "\n")
	if len(split) != len(codeLines) {
		return codeLines
	}
	return split
}

func (m whyModel) viewBrowseHeader() string {
	row := m.selectedRow()
	if row == nil {
		return fmt.Sprintf("%s  %s", m.styles.render(m.styles.sectionTitle, "ENTIRE WHY"), m.path)
	}

	lines := []string{
		truncateWhyDisplayField(fmt.Sprintf("%s  %s", m.styles.render(m.styles.sectionTitle, "ENTIRE WHY"), m.path), max(m.width, 20)),
		truncateWhyDisplayField(renderWhyMetaLine(
			"Line", itoa(row.LineNumber),
			"Commit", whyRowCommitHash(*row),
			"Author", row.Commit.Author,
			"When", row.Commit.WhenText,
		), max(m.width, 20)),
	}

	checkpointValue := "-"
	agentValue := "-"
	summaryLabel := "Subject"
	summaryValue := row.Commit.Subject
	if row.Entire != nil {
		if row.Entire.CheckpointID != "" {
			checkpointValue = row.Entire.CheckpointID
		}
		if row.Entire.Agent != "" {
			agentValue = row.Entire.Agent
		}
		if row.Entire.Summary != "" {
			summaryValue = row.Entire.Summary
			if row.Entire.IsFallback {
				summaryLabel = "Fallback"
			} else {
				summaryLabel = "Summary"
			}
		}
	}

	lines = append(lines, truncateWhyDisplayField(renderWhyMetaLine(
		"Checkpoint", checkpointValue,
		"Agent", agentValue,
		summaryLabel, summaryValue,
	), max(m.width, 20)))
	return strings.Join(lines, "\n")
}

func renderWhyMetaLine(parts ...string) string {
	fields := make([]string, 0, len(parts)/2)
	for i := 0; i+1 < len(parts); i += 2 {
		if strings.TrimSpace(parts[i+1]) == "" {
			continue
		}
		fields = append(fields, fmt.Sprintf("%s: %s", parts[i], parts[i+1]))
	}
	return strings.Join(fields, "  |  ")
}

func renderWhyHighlightedCode(path, code string) string {
	if strings.TrimSpace(code) == "" {
		return code
	}

	styleName := "dracula"
	if styles.Get(styleName) == nil {
		styleName = "monokai"
	}

	formatter := "terminal256"
	if formatters.Get(formatter) == nil {
		return code
	}

	lexer := lexers.Match(path)
	if lexer == nil {
		lexer = lexers.Match(filepath.Base(path))
	}
	if lexer == nil {
		lexer = lexers.Analyse(code)
	}
	if lexer == nil {
		return code
	}

	var b strings.Builder
	if err := quick.Highlight(&b, code, lexer.Config().Name, formatter, styleName); err != nil {
		return code
	}

	return strings.TrimRight(b.String(), "\n")
}

func (m whyModel) renderDetailContent(block whyBlock) string {
	switch whyBlockDetailKind(block) {
	case whyDetailCheckpoint:
		if m.checkpointDetail != nil {
			return m.renderCheckpointDetail()
		}
		return "checkpoint detail unavailable"
	default:
		diff, err := loadWhyCommitDiff(m.ctx, m.path, block.Commit.Hash)
		if err != nil {
			diff = fmt.Sprintf("unavailable: %v", err)
		}
		return renderWhyCommitDetail(whyCommitDetail{
			Commit: block.Commit,
			Diff:   diff,
		})
	}
}

func (m whyModel) renderCheckpointDetail() string {
	if m.checkpointDetail == nil {
		return ""
	}

	base := renderWhyCheckpointDetail(*m.checkpointDetail)
	if len(m.checkpointDetail.Sessions) == 0 {
		return base
	}

	var sb strings.Builder
	sb.WriteString(base)
	sb.WriteString("\nSession List:\n")
	for i, session := range m.checkpointDetail.Sessions {
		prefix := "  "
		if i == m.sessionCursor {
			prefix = "> "
		}
		fmt.Fprintf(&sb, "%s[%d] %s  Agent: %s  Created: %s\n",
			prefix,
			i+1,
			session.SessionID,
			emptyWhyValue(session.Agent, "-"),
			emptyWhyValue(session.CreatedAtText, "-"),
		)
	}
	return strings.TrimRight(sb.String(), "\n")
}

func whyBlockDetailKind(block whyBlock) whyDetailKind {
	if block.Detail != "" {
		return block.Detail
	}
	if block.Entire != nil {
		return whyDetailCheckpoint
	}
	return whyDetailCommit
}

func (m whyModel) viewDetail() string {
	var b strings.Builder
	block := m.selectedBlock()
	if block == nil {
		return ""
	}

	title := fmt.Sprintf("DETAIL  %s  %s", block.RangeText(), m.path)
	b.WriteString(title)
	b.WriteString("\n")
	b.WriteString(m.styles.horizontalRule(max(m.width, 20)))
	b.WriteString("\n")
	b.WriteString(m.detailVP.View())
	b.WriteString("\n")
	b.WriteString(m.viewDetailHelp())

	return b.String()
}

func (m whyModel) viewSessionDetail() string {
	var b strings.Builder
	block := m.selectedBlock()
	if block == nil {
		return ""
	}

	title := fmt.Sprintf("SESSION DETAIL  %s  %s", block.RangeText(), m.path)
	b.WriteString(title)
	b.WriteString("\n")
	b.WriteString(m.styles.horizontalRule(max(m.width, 20)))
	b.WriteString("\n")
	b.WriteString(m.detailVP.View())
	b.WriteString("\n")
	b.WriteString(m.viewDetailHelp())

	return b.String()
}

