type whyMode int

const (
	whyModeBrowse whyMode = iota
	whyModeDetail
	whyModeSessionDetail
)

type whyStyles struct {
	statusStyles

	sectionTitle lipgloss.Style
	selected     lipgloss.Style
	label        lipgloss.Style
	helpKey      lipgloss.Style
	helpSep      lipgloss.Style
	panelBorder  lipgloss.Style
	codeBorder   lipgloss.Style
}

func newWhyStyles(ss statusStyles) whyStyles {
	s := whyStyles{statusStyles: ss}
	if !ss.colorEnabled {
		return s
	}

	s.sectionTitle = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("244"))
	s.selected = lipgloss.NewStyle().Foreground(lipgloss.Color("214")).Bold(true)
	s.label = lipgloss.NewStyle().Foreground(lipgloss.Color("244"))
	s.helpKey = lipgloss.NewStyle().Foreground(lipgloss.Color("245"))
	s.helpSep = lipgloss.NewStyle().Foreground(lipgloss.Color("240"))
	s.panelBorder = lipgloss.NewStyle().
		Border(lipgloss.RoundedBorder()).
		BorderForeground(lipgloss.Color("243")).
		Padding(0, 1)
	s.codeBorder = lipgloss.NewStyle().
		Border(lipgloss.RoundedBorder()).
		BorderForeground(lipgloss.Color("240")).
		Padding(0, 1)

	return s
}

type whyModel struct {
	ctx    context.Context
	path   string
	blocks []whyBlock
	rows   []whyRow

	cursor int
	width  int
	height int
	mode   whyMode

	styles           whyStyles
	browseVP         viewport.Model
	detailVP         viewport.Model
	checkpointDetail *whyCheckpointDetail
	sessionCursor    int
	sessionDetail    *whySessionDetail
}

func newWhyModel(ctx context.Context, path string, blocks []whyBlock, ss statusStyles) whyModel {
	m := whyModel{
		ctx:      ctx,
		path:     path,
		blocks:   blocks,
		rows:     flattenWhyRows(blocks),
		width:    ss.width,
		mode:     whyModeBrowse,
		styles:   newWhyStyles(ss),
		browseVP: viewport.New(ss.width, 1),
	}
	return m.refreshBrowseContent()
}

func (m whyModel) Init() tea.Cmd {
	return nil
}

func (m whyModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) { //nolint:ireturn,cyclop // bubbletea interface
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.browseVP.Width = msg.Width
		m.browseVP.Height = max(msg.Height-4, 1)
		if m.mode == whyModeDetail || m.mode == whyModeSessionDetail {
			m.detailVP.Width = msg.Width
			m.detailVP.Height = max(msg.Height-3, 1)
		}
		m = m.refreshBrowseContent()
		return m, nil
	case tea.KeyMsg:
		switch m.mode {
		case whyModeDetail:
			return m.updateDetailMode(msg)
		case whyModeSessionDetail:
			return m.updateSessionDetailMode(msg)
		default:
			return m.updateBrowseMode(msg)
		}
	}

	return m, nil
}

func (m whyModel) updateBrowseMode(msg tea.KeyMsg) (tea.Model, tea.Cmd) { //nolint:ireturn // bubbletea pattern
	switch msg.String() {
	case "q", "ctrl+c":
		return m, tea.Quit
	case "up", "k":
		if m.cursor > 0 {
			m.cursor--
			m = m.refreshBrowseContent()
		}
	case "down", "j":
		if m.cursor < len(m.rows)-1 {
			m.cursor++
			m = m.refreshBrowseContent()
		}
	case "enter", " ":
		if block := m.selectedBlock(); block != nil {
			m.mode = whyModeDetail
			m.detailVP = viewport.New(m.width, max(m.height-3, 1))
			m.sessionCursor = 0
			m.sessionDetail = nil
			if whyBlockDetailKind(*block) == whyDetailCheckpoint {
				detail, err := loadWhyCheckpointDetail(m.ctx, m.path, *block)
				if err == nil {
					m.checkpointDetail = detail
					m.detailVP.SetContent(m.renderCheckpointDetail())
					return m, nil
				}
				m.checkpointDetail = nil
				m.detailVP.SetContent(fmt.Sprintf("checkpoint detail unavailable: %v", err))
				return m, nil
			}
			m.checkpointDetail = nil
			m.detailVP.SetContent(m.renderDetailContent(*block))
			return m, nil
		}
	default:
		var cmd tea.Cmd
		m.browseVP, cmd = m.browseVP.Update(msg)
		return m, cmd
	}

	return m, nil
}

func (m whyModel) updateDetailMode(msg tea.KeyMsg) (tea.Model, tea.Cmd) { //nolint:ireturn // bubbletea pattern
	if m.checkpointDetail != nil {
		switch msg.String() {
		case "esc", "backspace":
			m.mode = whyModeBrowse
			m.checkpointDetail = nil
			m.sessionDetail = nil
			return m, nil
		case "up", "k":
			if m.sessionCursor > 0 {
				m.sessionCursor--
				m.detailVP.SetContent(m.renderCheckpointDetail())
			}
			return m, nil
		case "down", "j":
			if m.sessionCursor < len(m.checkpointDetail.Sessions)-1 {
				m.sessionCursor++
				m.detailVP.SetContent(m.renderCheckpointDetail())
			}
			return m, nil
		case "enter", " ":
			sessionDetail := loadWhySessionDetail(m.checkpointDetail, m.sessionCursor)
			if sessionDetail != nil {
				m.mode = whyModeSessionDetail
				m.sessionDetail = sessionDetail
				m.detailVP.SetContent(renderWhySessionDetail(*sessionDetail))
			}
			return m, nil
		case "q", "ctrl+c":
			return m, tea.Quit
		}
	}

	switch msg.String() {
	case "esc", "backspace":
		m.mode = whyModeBrowse
		m.checkpointDetail = nil
		m.sessionDetail = nil
		return m, nil
	case "q", "ctrl+c":
		return m, tea.Quit
	}

	var cmd tea.Cmd
	m.detailVP, cmd = m.detailVP.Update(msg)
	return m, cmd
}

func (m whyModel) updateSessionDetailMode(msg tea.KeyMsg) (tea.Model, tea.Cmd) { //nolint:ireturn // bubbletea pattern
	switch msg.String() {
	case "esc", "backspace":
		m.mode = whyModeDetail
		m.sessionDetail = nil
		m.detailVP.SetContent(m.renderCheckpointDetail())
		return m, nil
	case "q", "ctrl+c":
		return m, tea.Quit
	}

	var cmd tea.Cmd
	m.detailVP, cmd = m.detailVP.Update(msg)
	return m, cmd
}

func (m whyModel) View() string {
	if m.width == 0 {
		return ""
	}

	if m.mode == whyModeDetail {
		return m.viewDetail()
	}
	if m.mode == whyModeSessionDetail {
		return m.viewSessionDetail()
	}

	return strings.Join([]string{
		m.viewBrowseHeader(),
		renderWhyInteractiveHeader(),
		m.styles.horizontalRule(max(m.width, 20)),
		m.browseVP.View(),
		m.viewHelp(),
	}, "\n")
}

func (m whyModel) refreshBrowseContent() whyModel {
	m.browseVP.SetContent(m.renderBrowseContent())
	return m.ensureBrowseCursorVisible()
}

func (m whyModel) ensureBrowseCursorVisible() whyModel {
	if m.browseVP.Height <= 0 {
		return m
	}
	if m.cursor < m.browseVP.YOffset {
		m.browseVP.YOffset = m.cursor
	}
	if m.cursor >= m.browseVP.YOffset+m.browseVP.Height {
		m.browseVP.YOffset = m.cursor - m.browseVP.Height + 1
	}
	return m
}

func (m whyModel) selectedRow() *whyRow {
	if m.cursor < 0 || m.cursor >= len(m.rows) {
		return nil
	}
	return &m.rows[m.cursor]
}

func (m whyModel) selectedBlock() *whyBlock {
	row := m.selectedRow()
	if row == nil || row.BlockIndex < 0 || row.BlockIndex >= len(m.blocks) {
		return nil
	}
	return &m.blocks[row.BlockIndex]
}

