package cli

import (
	"fmt"
	"strings"
)

const (
	whyCommitWidth     = 10
	whyAuthorWidth     = 18
	whyCheckpointWidth = 12
	whyAgentWidth      = 12
	whyLineWidth       = 4
)

func renderWhyCheckpointDetail(detail whyCheckpointDetail) string {
	var sb strings.Builder

	if detail.Entire.CheckpointID != "" {
		fmt.Fprintf(&sb, "Checkpoint: %s\n", detail.Entire.CheckpointID)
	}
	if detail.Entire.Agent != "" {
		fmt.Fprintf(&sb, "Agent: %s\n", detail.Entire.Agent)
	}
	if detail.Entire.Summary != "" {
		if detail.Entire.IsFallback {
			fmt.Fprintf(&sb, "Fallback Summary: %s\n", detail.Entire.Summary)
		} else {
			fmt.Fprintf(&sb, "Generated Summary: %s\n", detail.Entire.Summary)
		}
	}

	hash := detail.Commit.Hash
	if hash == "" {
		hash = detail.Commit.ShortHash
	}
	if hash != "" {
		fmt.Fprintf(&sb, "Commit: %s\n", hash)
	}
	if detail.Commit.Author != "" {
		fmt.Fprintf(&sb, "Author: %s\n", detail.Commit.Author)
	}
	if detail.Commit.WhenText != "" {
		fmt.Fprintf(&sb, "When: %s\n", detail.Commit.WhenText)
	}
	if detail.Commit.Subject != "" {
		fmt.Fprintf(&sb, "Subject: %s\n", detail.Commit.Subject)
	}
	if len(detail.FilesTouched) > 0 {
		fmt.Fprintf(&sb, "Files: %s\n", strings.Join(detail.FilesTouched, ", "))
	}
	if detail.Diff != "" {
		sb.WriteString("Diff:\n")
		sb.WriteString(renderWhyHighlightedDiff(detail.Diff))
		if !strings.HasSuffix(detail.Diff, "\n") {
			sb.WriteString("\n")
		}
	}
	return sb.String()
}

func renderWhySessionDetail(detail whySessionDetail) string {
	var sb strings.Builder

	fmt.Fprintf(&sb, "Checkpoint: %s\n", detail.Checkpoint)
	fmt.Fprintf(&sb, "Session: %s\n", detail.Session.SessionID)
	if detail.Session.Agent != "" {
		fmt.Fprintf(&sb, "Agent: %s\n", detail.Session.Agent)
	}
	if detail.Session.Model != "" {
		fmt.Fprintf(&sb, "Model: %s\n", detail.Session.Model)
	}
	if detail.Session.CreatedAtText != "" {
		fmt.Fprintf(&sb, "Created: %s\n", detail.Session.CreatedAtText)
	}
	if detail.Session.CheckpointsCount > 0 {
		fmt.Fprintf(&sb, "Checkpoints: %d\n", detail.Session.CheckpointsCount)
	}
	if len(detail.Session.FilesTouched) > 0 {
		fmt.Fprintf(&sb, "Files: %s\n", strings.Join(detail.Session.FilesTouched, ", "))
	}
	if detail.Session.Summary != "" {
		if detail.Session.IsFallback {
			fmt.Fprintf(&sb, "Fallback Summary: %s\n", detail.Session.Summary)
		} else {
			fmt.Fprintf(&sb, "Generated Summary: %s\n", detail.Session.Summary)
		}
	}
	if detail.Commit.Hash != "" {
		fmt.Fprintf(&sb, "Commit: %s\n", detail.Commit.Hash)
	}
	if detail.Commit.Author != "" {
		fmt.Fprintf(&sb, "Author: %s\n", detail.Commit.Author)
	}

	return sb.String()
}

func renderWhyCommitDetail(detail whyCommitDetail) string {
	var sb strings.Builder

	hash := detail.Commit.Hash
	if hash == "" {
		hash = detail.Commit.ShortHash
	}

	if hash != "" {
		fmt.Fprintf(&sb, "Commit: %s\n", hash)
	}
	if detail.Commit.Author != "" {
		fmt.Fprintf(&sb, "Author: %s\n", detail.Commit.Author)
	}
	if detail.Commit.WhenText != "" {
		fmt.Fprintf(&sb, "When: %s\n", detail.Commit.WhenText)
	}
	if detail.Commit.Subject != "" {
		fmt.Fprintf(&sb, "Subject: %s\n", detail.Commit.Subject)
	}
	if detail.Diff != "" {
		sb.WriteString("Diff:\n")
		sb.WriteString(renderWhyHighlightedDiff(detail.Diff))
		if !strings.HasSuffix(detail.Diff, "\n") {
			sb.WriteString("\n")
		}
	}

	return sb.String()
}

func renderWhyStatic(blocks []whyBlock) string {
	var sb strings.Builder
	rows := flattenWhyRows(blocks)

	if len(rows) == 0 {
		return ""
	}

	sb.WriteString(renderWhyStaticHeader())
	sb.WriteString("\n")

	for i, row := range rows {
		if i > 0 {
			sb.WriteString("\n")
		}
		fmt.Fprintf(&sb, "%s | %s", renderWhyRowGutter(row), row.CodeLine)
	}

	return sb.String()
}

func renderWhyStaticHeader() string {
	return strings.Join([]string{
		padWhyField("COMMIT", whyCommitWidth),
		padWhyField("AUTHOR", whyAuthorWidth),
		padWhyField("CHECKPOINT", whyCheckpointWidth),
		padWhyField("AGENT", whyAgentWidth),
		padWhyField("LINE", whyLineWidth),
	}, " ") + " | CODE"
}

func emptyWhyValue(value, fallback string) string {
	if strings.TrimSpace(value) == "" {
		return fallback
	}
	return value
}

func renderWhyRowGutter(row whyRow) string {
	return strings.Join([]string{
		padWhyField(whyRowCommitHash(row), whyCommitWidth),
		padWhyField(row.Commit.Author, whyAuthorWidth),
		padWhyField(whyRowCheckpointID(row), whyCheckpointWidth),
		padWhyField(whyRowAgent(row), whyAgentWidth),
		padWhyField(itoa(row.LineNumber), whyLineWidth),
	}, " ")
}

func whyRowCommitHash(row whyRow) string {
	if row.Commit.ShortHash != "" {
		return row.Commit.ShortHash
	}
	return row.Commit.Hash
}

func whyRowCheckpointID(row whyRow) string {
	if row.Entire == nil || row.Entire.CheckpointID == "" {
		return "-"
	}
	return row.Entire.CheckpointID
}

func whyRowAgent(row whyRow) string {
	if row.Entire == nil || row.Entire.Agent == "" {
		return "-"
	}
	return row.Entire.Agent
}

func padWhyField(value string, width int) string {
	value = truncateWhyDisplayField(value, width)
	if len([]rune(value)) >= width {
		return value
	}
	return value + strings.Repeat(" ", width-len([]rune(value)))
}

func truncateWhyDisplayField(value string, width int) string {
	if width <= 0 {
		return value
	}

	runes := []rune(value)
	if len(runes) <= width {
		return value
	}
	if width == 1 {
		return string(runes[:1])
	}
	return string(runes[:width-1]) + "…"
}

func renderWhyHighlightedDiff(diff string) string {
	if strings.TrimSpace(diff) == "" {
		return diff
	}

	lines := strings.Split(diff, "\n")
	rendered := make([]string, 0, len(lines))
	for _, line := range lines {
		rendered = append(rendered, renderWhyDiffLine(line))
	}
	return strings.Join(rendered, "\n")
}

func renderWhyInteractiveGutter(row whyRow) string {
	return strings.Join([]string{
		padWhyField(whyRowCommitHash(row), whyCommitWidth),
		padWhyField(row.Commit.Author, whyAuthorWidth),
		padWhyField(whyRowCheckpointID(row), whyCheckpointWidth),
		padWhyField(itoa(row.LineNumber), whyLineWidth),
	}, " ")
}

func renderWhyInteractiveHeader() string {
	return strings.Join([]string{
		padWhyField("COMMIT", whyCommitWidth),
		padWhyField("AUTHOR", whyAuthorWidth),
		padWhyField("CHECKPOINT", whyCheckpointWidth),
		padWhyField("LINE", whyLineWidth),
	}, " ") + " | CODE"
}

func renderWhyDiffLine(line string) string {
	switch {
	case strings.HasPrefix(line, "+++") || strings.HasPrefix(line, "---"):
		return line
	case strings.HasPrefix(line, "@@"):
		return line
	case strings.HasPrefix(line, "+"):
		return colorizeDiffPrefix("+", "green") + renderWhyHighlightedCode("", line[1:])
	case strings.HasPrefix(line, "-"):
		return colorizeDiffPrefix("-", "red") + renderWhyHighlightedCode("", line[1:])
	case strings.HasPrefix(line, " "):
		return " " + renderWhyHighlightedCode("", line[1:])
	default:
		return line
	}
}

func colorizeDiffPrefix(prefix, color string) string {
	switch color {
	case "green":
		return "\x1b[32m" + prefix + "\x1b[0m"
	case "red":
		return "\x1b[31m" + prefix + "\x1b[0m"
	default:
		return prefix
	}
}

