func selectWhySummary(summary *checkpoint.Summary, commitSubject string) (string, bool) {
	if summary != nil {
		if text := strings.TrimSpace(summary.Outcome); text != "" {
			return text, false
		}
		if text := strings.TrimSpace(summary.Intent); text != "" {
			return text, true
		}
	}

	if text := strings.TrimSpace(commitSubject); text != "" {
		return text, true
	}

	return "", true
}

func commitSubject(message string) string {
	subject, _, found := strings.Cut(message, "\n")
	if found {
		return strings.TrimSpace(subject)
	}
	return strings.TrimSpace(message)
}

var loadWhyCommitDiff = loadWhyCommitDiffImpl

var loadWhyCheckpointDetail = loadWhyCheckpointDetailImpl
var loadWhySessionDetail = loadWhySessionDetailImpl

func loadWhyCheckpointDetailImpl(ctx context.Context, path string, block whyBlock) (*whyCheckpointDetail, error) {
	if block.Entire == nil {
		return nil, errors.New("block has no Entire checkpoint metadata")
	}

	checkpointID, err := id.NewCheckpointID(block.Entire.CheckpointID)
	if err != nil {
		return nil, err
	}

	repo, err := openRepository(ctx)
	if err != nil {
		return nil, err
	}

	v1Store := checkpoint.NewGitStore(repo)
	v2Store := checkpoint.NewV2GitStore(repo, "origin")
	reader, summary, err := checkpoint.ResolveCommittedReaderForCheckpoint(ctx, checkpointID, v1Store, v2Store, true)
	if err != nil {
		return nil, err
	}

	diff, err := loadWhyCommitDiff(ctx, path, block.Commit.Hash)
	if err != nil {
		diff = fmt.Sprintf("unavailable: %v", err)
	}

	detail := &whyCheckpointDetail{
		Commit: block.Commit,
		Entire: *block.Entire,
		Diff:   diff,
	}
	if summary == nil {
		return detail, nil
	}

	detail.FilesTouched = append(detail.FilesTouched, summary.FilesTouched...)
	detail.TokenUsage = formatWhyTokenUsage(summary.TokenUsage)
	for sessionIndex := range len(summary.Sessions) {
		sessionMetadata, err := readWhySessionMetadata(ctx, reader, checkpointID, sessionIndex)
		if err != nil {
			return nil, err
		}
		if sessionMetadata == nil {
			continue
		}
		summaryText, isFallback := selectWhySummary(sessionMetadata.Summary, block.Commit.Subject)
		detail.Sessions = append(detail.Sessions, whySessionSummary{
			Index:            sessionIndex,
			SessionID:        sessionMetadata.SessionID,
			CreatedAtText:    sessionMetadata.CreatedAt.Local().Format("2006-01-02 15:04:05"),
			Agent:            string(sessionMetadata.Agent),
			Model:            sessionMetadata.Model,
			Summary:          summaryText,
			IsFallback:       isFallback,
			TokenUsage:       formatWhyTokenUsage(sessionMetadata.TokenUsage),
			CheckpointsCount: sessionMetadata.CheckpointsCount,
			FilesTouched:     append([]string(nil), sessionMetadata.FilesTouched...),
		})
	}

	return detail, nil
}

func loadWhySessionDetailImpl(ctx context.Context, checkpointDetail *whyCheckpointDetail, sessionIndex int) (*whySessionDetail, error) {
	if checkpointDetail == nil || sessionIndex < 0 || sessionIndex >= len(checkpointDetail.Sessions) {
		return nil, errors.New("invalid checkpoint session selection")
	}

	checkpointID, err := id.NewCheckpointID(checkpointDetail.Entire.CheckpointID)
	if err != nil {
		return nil, err
	}

	repo, err := openRepository(ctx)
	if err != nil {
		return nil, err
	}

	v1Store := checkpoint.NewGitStore(repo)
	v2Store := checkpoint.NewV2GitStore(repo, "origin")
	reader, _, err := checkpoint.ResolveCommittedReaderForCheckpoint(ctx, checkpointID, v1Store, v2Store, true)
	if err != nil {
		return nil, err
	}

	content, err := readWhySessionContent(ctx, reader, checkpointID, sessionIndex)
	if err != nil {
		return nil, err
	}

	session := checkpointDetail.Sessions[sessionIndex]
	detail := &whySessionDetail{
		Commit:       checkpointDetail.Commit,
		Checkpoint:   checkpointDetail.Entire.CheckpointID,
		Session:      session,
		Prompts:      strings.TrimSpace(content.Prompts),
		Transcript:   strings.TrimSpace(string(content.Transcript)),
		TranscriptID: content.Metadata.TranscriptIdentifierAtStart,
	}
	return detail, nil
}

var readWhySessionContent = func(ctx context.Context, reader checkpoint.CommittedReader, checkpointID id.CheckpointID, sessionIndex int) (*checkpoint.SessionContent, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}

	switch r := reader.(type) {
	case interface {
		ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*checkpoint.SessionContent, error)
	}:
		return r.ReadSessionContent(ctx, checkpointID, sessionIndex)
	case interface {
		ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*checkpoint.SessionContent, error)
	}:
		return r.ReadSessionMetadataAndPrompts(ctx, checkpointID, sessionIndex)
	default:
		return nil, fmt.Errorf("reader does not support session content reads")
	}
}

func formatWhyTokenUsage(tokenUsage *agent.TokenUsage) string {
	if tokenUsage == nil {
		return ""
	}
	total := tokenUsage.InputTokens + tokenUsage.CacheCreationTokens + tokenUsage.CacheReadTokens + tokenUsage.OutputTokens
	if total <= 0 && tokenUsage.APICallCount <= 0 {
		return ""
	}
	if tokenUsage.APICallCount > 0 {
		return fmt.Sprintf("%d tokens across %d API calls", total, tokenUsage.APICallCount)
	}
	return fmt.Sprintf("%d tokens", total)
}

func loadWhyCommitDiffImpl(ctx context.Context, path, commitHash string) (string, error) {
	if strings.TrimSpace(commitHash) == "" {
		return "", nil
	}

	repoRoot, targetPath, err := resolveWhyBlameTargetPath(ctx, path)
	if err != nil {
		return "", err
	}

	return runGitShowWhyCommitDiff(ctx, repoRoot, commitHash, targetPath)
}

var runGitShowWhyCommitDiff = func(ctx context.Context, repoRoot, commitHash, path string) (string, error) {
	cmd := exec.CommandContext(ctx, "git", "show", "--format=", "--no-ext-diff", commitHash, "--", path)
	cmd.Dir = repoRoot

	output, err := cmd.CombinedOutput()
	if err != nil {
		return "", fmt.Errorf("git show %s -- %s: %w: %s", commitHash, path, err, strings.TrimSpace(string(output)))
	}

	return string(output), nil
}

func newWhyCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "why <path>",
		Short: "Show why lines exist in a file",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			out := cmd.OutOrStdout()
			blocks, err := loadWhyDisplayData(ctx, args[0])
			if err != nil {
				return fmt.Errorf("loading why data for %s: %w", args[0], err)
			}

			if shouldRunWhyTUI(out) {
				if err := runWhyTUI(ctx, out, args[0], blocks); err != nil {
					return fmt.Errorf("TUI error: %w", err)
				}
				return nil
			}

			if err := writeWhyStaticOutput(out, renderWhyStatic(blocks)); err != nil {
				return fmt.Errorf("writing why output for %s: %w", args[0], err)
			}
			return nil
		},
	}

	return cmd
}

