// wrong commit. Non-hex refs (HEAD, branch names, HEAD~1) bypass the
// ambiguity check via commitHashesWithPrefix returning nil.
func resolveCommitUnambiguous(repo *git.Repository, ref string) (plumbing.Hash, error) {
