// FormatCondensedTranscript formats an Input into a human-readable string for LLM.
// The format is:
//
//	[User] user prompt here
//
//	[Assistant] assistant response here
//
//	[Tool] ToolName: description or file path
func FormatCondensedTranscript(input Input) string {
	var sb strings.Builder

	for i, entry := range input.Transcript {
		if i > 0 {
			sb.WriteString("\n")
		}

		switch entry.Type {
		case EntryTypeUser:
			sb.WriteString("[User] ")
			sb.WriteString(entry.Content)
			sb.WriteString("\n")
		case EntryTypeAssistant:
			sb.WriteString("[Assistant] ")
			sb.WriteString(entry.Content)
			sb.WriteString("\n")
		case EntryTypeTool:
			sb.WriteString("[Tool] ")
			sb.WriteString(entry.ToolName)
			if entry.ToolDetail != "" {
				sb.WriteString(": ")
				sb.WriteString(entry.ToolDetail)
			}
			sb.WriteString("\n")
		}
	}

	if len(input.FilesTouched) > 0 {
		sb.WriteString("\n[Files Modified]\n")
		for _, file := range input.FilesTouched {
			fmt.Fprintf(&sb, "- %s\n", file)
		}
	}

	return sb.String()
}

package cli

import (
	"strconv"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
)

type whyCommitInfo struct {
	Hash      string
	ShortHash string
	Author    string
	Email     string
	WhenText  string
	Subject   string
}

type whyEntireInfo struct {
	CheckpointID string
	Agent        string
	Summary      string
	IsFallback   bool
}

type whyCheckpointDetail struct {
	Commit       whyCommitInfo
	Entire       whyEntireInfo
	Diff         string
	FilesTouched []string
	TokenUsage   string
	Sessions     []whySessionSummary
}

type whySessionSummary struct {
	Index            int
	SessionID        string
	CreatedAtText    string
	Agent            string
	Model            string
	Summary          string
	IsFallback       bool
	TokenUsage       string
	CheckpointsCount int
	FilesTouched     []string
}

type whySessionDetail struct {
	Commit       whyCommitInfo
	Checkpoint   string
	Session      whySessionSummary
	AgentType    types.AgentType
	Prompts      string
	Transcript   string
	TranscriptID string
}

type whyCommitDetail struct {
	Commit whyCommitInfo
	Diff   string
}

type whyDetailKind string

const (
	whyDetailCheckpoint whyDetailKind = "checkpoint"
	whyDetailCommit     whyDetailKind = "commit"
)

type whyBlock struct {
	StartLine int
	EndLine   int
	Commit    whyCommitInfo
	Entire    *whyEntireInfo
	CodeLines []string
	Detail    whyDetailKind
}

type whyRow struct {
	BlockIndex     int
	LineNumber     int
	BlockStartLine int
	BlockEndLine   int
	Commit         whyCommitInfo
	Entire         *whyEntireInfo
	CodeLine       string
	Detail         whyDetailKind
}

func (b whyBlock) RangeText() string {
	if b.StartLine == b.EndLine {
		return itoa(b.StartLine)
	}
	return itoa(b.StartLine) + "-" + itoa(b.EndLine)
}

func flattenWhyRows(blocks []whyBlock) []whyRow {
	if len(blocks) == 0 {
		return nil
	}

	rows := make([]whyRow, 0, len(blocks))
	for blockIndex, block := range blocks {
		for i, codeLine := range block.CodeLines {
			rows = append(rows, whyRow{
				BlockIndex:     blockIndex,
				LineNumber:     block.StartLine + i,
				BlockStartLine: block.StartLine,
				BlockEndLine:   block.EndLine,
				Commit:         block.Commit,
				Entire:         block.Entire,
				CodeLine:       codeLine,
				Detail:         block.Detail,
			})
		}
	}

	return rows
}

func itoa(v int) string {
	return strconv.Itoa(v)
}

package cli

import (
	"fmt"
	"strings"
)

const (
	whyCommitWidth     = 10
	whyAuthorWidth     = 18
	whyCheckpointWidth = 12
	whyAgentWidth      = 12
	whyLineWidth       = 4
)

func renderWhyCheckpointDetail(detail whyCheckpointDetail) string {
	var sb strings.Builder
	sb.WriteString(renderWhyCheckpointMetadata(detail))
	if detail.Diff != "" {
		sb.WriteString("\n=== File Diff ===\n")
		sb.WriteString(renderWhyHighlightedDiff(detail.Diff))
		if !strings.HasSuffix(detail.Diff, "\n") {
			sb.WriteString("\n")
		}
	}
	return sb.String()
}

func renderWhyCheckpointMetadata(detail whyCheckpointDetail) string {
	var sb strings.Builder

	sb.WriteString("=== Checkpoint Metadata ===\n")
	if detail.Entire.CheckpointID != "" {
		fmt.Fprintf(&sb, "Checkpoint: %s\n", detail.Entire.CheckpointID)
	}
	if detail.Entire.Agent != "" {
		fmt.Fprintf(&sb, "Agent: %s\n", detail.Entire.Agent)
	}
	if detail.Entire.Summary != "" {
		if detail.Entire.IsFallback {
			fmt.Fprintf(&sb, "Fallback Summary: %s\n", detail.Entire.Summary)
		} else {
			fmt.Fprintf(&sb, "Generated Summary: %s\n", detail.Entire.Summary)
		}
	}
	if detail.TokenUsage != "" {
