func (m whyModel) handlePagerJumpBrowse(msg tea.KeyMsg) (whyModel, bool) {
	switch msg.String() {
	case "G":
		if len(m.rows) > 0 {
			m.cursor = len(m.rows) - 1
			m = m.refreshBrowseContent()
		}
		return m, true
	case "g":
		if len(m.rows) > 0 {
			m.cursor = 0
			m = m.refreshBrowseContent()
		}
		return m, true
	default:
		return m, false
	}
}

func (m whyModel) handlePagerJumpDetail(msg tea.KeyMsg) (whyModel, bool) {
	switch msg.String() {
	case "G":
		m.detailVP.GotoBottom()
		return m, true
	case "g":
		m.detailVP.GotoTop()
		return m, true
	default:
		return m, false
	}
