func TestNewWhyBrowserModel_ShowsDotfilesAndSortsDirectoriesFirst(t *testing.T) {
	origGetRoot := getWhyBrowserRoot
	origReadDir := readWhyBrowserDir
	t.Cleanup(func() {
		getWhyBrowserRoot = origGetRoot
		readWhyBrowserDir = origReadDir
	})

	root := t.TempDir()
	if err := os.WriteFile(filepath.Join(root, ".env"), []byte("KEY=value\n"), 0o644); err != nil {
		t.Fatalf("write dotfile: %v", err)
	}
	if err := os.Mkdir(filepath.Join(root, "src"), 0o755); err != nil {
		t.Fatalf("mkdir src: %v", err)
	}
	if err := os.WriteFile(filepath.Join(root, "README.md"), []byte("hello\n"), 0o644); err != nil {
		t.Fatalf("write readme: %v", err)
	}

	getWhyBrowserRoot = func() (string, error) {
		return root, nil
	}
	readWhyBrowserDir = os.ReadDir

	m, err := newWhyBrowserModel(context.Background(), statusStyles{colorEnabled: false, width: 100})
	if err != nil {
		t.Fatalf("newWhyBrowserModel error: %v", err)
	}

	if got, want := m.mode, whyModeBrowser; got != want {
		t.Fatalf("mode = %d, want %d", got, want)
	}
	if got, want := m.browserDir, root; got != want {
		t.Fatalf("browser dir = %q, want %q", got, want)
	}
	if len(m.browserEntries) != 3 {
		t.Fatalf("entry count = %d, want 3", len(m.browserEntries))
	}
	if got, want := m.browserEntries[0].Name, "src"; got != want {
		t.Fatalf("first entry = %q, want %q", got, want)
	}
	if !m.browserEntries[0].IsDir {
		t.Fatal("expected directories to sort first")
	}
	names := []string{m.browserEntries[0].Name, m.browserEntries[1].Name, m.browserEntries[2].Name}
	if !slices.Contains(names, ".env") {
		t.Fatalf("expected dotfile to be visible, got %v", names)
	}
}

