	origReadDir := readWhyBrowserDir
	t.Cleanup(func() {
		getWhyBrowserRoot = origGetRoot
		readWhyBrowserDir = origReadDir
	})

	root := t.TempDir()
	child := filepath.Join(root, "src")
	if err := os.Mkdir(child, 0o755); err != nil {
		t.Fatalf("mkdir src: %v", err)
	}
	if err := os.WriteFile(filepath.Join(root, "README.md"), []byte("hello\n"), 0o644); err != nil {
		t.Fatalf("write readme: %v", err)
	}
	if err := os.WriteFile(filepath.Join(child, "main.go"), []byte("package main\n"), 0o644); err != nil {
		t.Fatalf("write child file: %v", err)
	}

	getWhyBrowserRoot = func() (string, error) {
		return root, nil
	}
	readWhyBrowserDir = os.ReadDir

	m, err := newWhyBrowserModel(context.Background(), statusStyles{colorEnabled: false, width: 100})
	if err != nil {
		t.Fatalf("newWhyBrowserModel error: %v", err)
	}
	m.height = 20
	m.browserVP.Height = 16
	m = m.refreshBrowserContent()

	if got, want := m.browserEntries[m.browserCursor].Name, "src"; got != want {
		t.Fatalf("initial selected entry = %q, want %q", got, want)
	}

	m = updateWhyModel(t, m, tea.KeyMsg{Type: tea.KeyDown})
	if got, want := m.browserEntries[m.browserCursor].Name, "README.md"; got != want {
		t.Fatalf("selected entry after down = %q, want %q", got, want)
	}

	m = updateWhyModel(t, m, tea.KeyMsg{Type: tea.KeyUp})
	m = updateWhyModel(t, m, tea.KeyMsg{Type: tea.KeyEnter})

	if got, want := m.browserDir, child; got != want {
		t.Fatalf("browser dir after enter = %q, want %q", got, want)
	}
	if len(m.browserEntries) != 1 || m.browserEntries[0].Name != "main.go" {
		t.Fatalf("child entries = %+v, want main.go only", m.browserEntries)
	}

	m = updateWhyModel(t, m, tea.KeyMsg{Type: tea.KeyBackspace})
	if got, want := m.browserDir, root; got != want {
		t.Fatalf("browser dir after back = %q, want %q", got, want)
	}
	if got, want := m.browserEntries[m.browserCursor].Name, "src"; got != want {
		t.Fatalf("restored selection = %q, want %q", got, want)
	}
}

