func (m whyModel) renderCheckpointDetail() string {
	if m.checkpointDetail == nil {
		return ""
	}

	var sb strings.Builder
	sb.WriteString(m.styleWhyDetailContent(renderWhyCheckpointMetadata(*m.checkpointDetail)))
	if len(m.checkpointDetail.Sessions) > 0 {
		sb.WriteString("\n")
		sb.WriteString(m.styles.render(m.styles.detailTitle, "=== Sessions (j/k to select, enter to open) ==="))
		sb.WriteString("\n")
		sb.WriteString(m.styles.render(m.styles.tableHeader, "    ID           AGENT         MODEL                TOKENS                    CREATED              TYPE                 SUMMARY"))
		sb.WriteString("\n")
		for i, session := range m.checkpointDetail.Sessions {
			prefix := "  "
			if i == m.sessionCursor {
				prefix = "> "
			}
			row := fmt.Sprintf("%s[%d] %-12s %-13s %-20s %-24s %-20s %-20s %s",
				prefix,
				i+1,
				session.SessionID,
				emptyWhyValue(session.Agent, "-"),
				emptyWhyValue(session.Model, "-"),
				truncateWhyDisplayField(emptyWhyValue(session.TokenUsage, "-"), 24),
				emptyWhyValue(session.CreatedAtText, "-"),
				truncateWhyDisplayField(sessionSummaryLabel(session), 20),
				truncateWhyDisplayField(emptyWhyValue(session.Summary, "-"), 60),
			)
			if m.styles.colorEnabled {
				if i == m.sessionCursor {
					row = m.styles.render(m.styles.selected, row)
				} else {
					row = m.styleWhySessionRow(row)
				}
			}
			sb.WriteString(row)
			sb.WriteString("\n")
		}
	} else {
		sb.WriteString("\n")
		sb.WriteString(m.styles.render(m.styles.detailTitle, "=== Sessions ==="))
		sb.WriteString("\n")
		sb.WriteString(m.styles.render(m.styles.dim, "No sessions available."))
		sb.WriteString("\n")
	}
	if m.checkpointDetail.Diff != "" {
		sb.WriteString("\n")
		sb.WriteString(m.styles.render(m.styles.detailTitle, "=== File Diff ==="))
		sb.WriteString("\n")
		sb.WriteString(renderWhyHighlightedDiff(m.checkpointDetail.Diff))
		if !strings.HasSuffix(m.checkpointDetail.Diff, "\n") {
			sb.WriteString("\n")
		}
	}
	return strings.TrimRight(sb.String(), "\n")
}

