func (m whyModel) loadWhyBrowserDir(dir, preferredName string, fallbackCursor int, pushHistory bool) (whyModel, error) {
	entries, err := readWhyBrowserDir(dir)
	if err != nil {
		return m, fmt.Errorf("read %s: %w", dir, err)
	}

	if pushHistory && m.browserDir != "" {
		m.browserHistory = append(m.browserHistory, whyBrowserLocation{
			Dir:    m.browserDir,
			Cursor: m.browserCursor,
		})
	}

	m.browserDir = dir
	m.browserEntries = collectWhyBrowserEntries(dir, entries)
	m.browserErr = ""
	m.browserCursor = whyBrowserCursorForEntry(m.browserEntries, preferredName, fallbackCursor)
	return m.refreshBrowserContent(), nil
}

func (m whyModel) ascendWhyBrowserDir() (whyModel, error) {
	if len(m.browserHistory) > 0 {
		last := m.browserHistory[len(m.browserHistory)-1]
		m.browserHistory = slices.Delete(m.browserHistory, len(m.browserHistory)-1, len(m.browserHistory))
		return m.loadWhyBrowserDir(last.Dir, "", last.Cursor, false)
	}

	parent := filepath.Dir(m.browserDir)
	if parent == m.browserDir {
		return m, nil
	}
	return m.loadWhyBrowserDir(parent, filepath.Base(m.browserDir), 0, false)
}

func collectWhyBrowserEntries(dir string, entries []os.DirEntry) []whyBrowserEntry {
	out := make([]whyBrowserEntry, 0, len(entries))
	for _, entry := range entries {
		out = append(out, whyBrowserEntry{
			Name:  entry.Name(),
			Path:  filepath.Join(dir, entry.Name()),
			IsDir: entry.IsDir(),
		})
	}

	slices.SortFunc(out, func(a, b whyBrowserEntry) int {
		if a.IsDir != b.IsDir {
			if a.IsDir {
				return -1
			}
			return 1
		}

