}

func (m whyModel) updateBrowserMode(msg tea.KeyMsg) (tea.Model, tea.Cmd) { //nolint:ireturn // bubbletea pattern
	if next, handled := m.handlePagerJumpBrowser(msg); handled {
		return next, nil
	}

	switch msg.String() {
	case "q", "ctrl+c":
		return m, tea.Quit
	case "up", "k":
		if m.browserCursor > 0 {
			m.browserCursor--
			m = m.refreshBrowserContent()
		}
	case "down", "j":
		if m.browserCursor < len(m.browserEntries)-1 {
			m.browserCursor++
			m = m.refreshBrowserContent()
		}
	case "left", "h", "backspace":
		next, err := m.ascendWhyBrowserDir()
		if err != nil {
			m.browserErr = err.Error()
			m = m.refreshBrowserContent()
			return m, nil
		}
		return next, nil
	case "enter", " ":
		entry := m.selectedBrowserEntry()
		if entry == nil {
			return m, nil
		}
		if !entry.IsDir {
			next, err := m.openWhyBrowserFile(entry.Path)
			if err != nil {
				m.browserErr = err.Error()
				m = m.refreshBrowserContent()
				return m, nil
			}
			return next, nil
		}
		next, err := m.loadWhyBrowserDir(entry.Path, "", 0, true)
		if err != nil {
			m.browserErr = err.Error()
			m = m.refreshBrowserContent()
			return m, nil
		}
		return next, nil
	default:
		var cmd tea.Cmd
		m.browserVP, cmd = m.browserVP.Update(msg)
		return m, cmd
	}

	return m, nil
}

