package cli

import (
	"fmt"
	"strings"
)

const (
	whyCommitWidth     = 10
	whyAuthorWidth     = 18
	whyCheckpointWidth = 12
	whyAgentWidth      = 12
	whyLineWidth       = 4
)

func renderWhyCheckpointDetail(detail whyCheckpointDetail) string {
	var sb strings.Builder
	sb.WriteString(renderWhyCheckpointMetadata(detail))
	if detail.Diff != "" {
		sb.WriteString("\n=== File Diff ===\n")
		sb.WriteString(renderWhyHighlightedDiff(detail.Diff))
		if !strings.HasSuffix(detail.Diff, "\n") {
			sb.WriteString("\n")
		}
	}
	return sb.String()
}

func renderWhyCheckpointMetadata(detail whyCheckpointDetail) string {
	var sb strings.Builder

	sb.WriteString("=== Checkpoint Metadata ===\n")
	if detail.Entire.CheckpointID != "" {
		fmt.Fprintf(&sb, "Checkpoint: %s\n", detail.Entire.CheckpointID)
	}
	if detail.Entire.Agent != "" {
		fmt.Fprintf(&sb, "Agent: %s\n", detail.Entire.Agent)
	}
	if detail.Entire.Summary != "" {
		if detail.Entire.IsFallback {
			fmt.Fprintf(&sb, "Fallback Summary: %s\n", detail.Entire.Summary)
		} else {
			fmt.Fprintf(&sb, "Generated Summary: %s\n", detail.Entire.Summary)
		}
	}
	if detail.TokenUsage != "" {
		fmt.Fprintf(&sb, "Tokens: %s\n", detail.TokenUsage)
	}
	if len(detail.Sessions) > 0 {
		fmt.Fprintf(&sb, "Sessions: %d\n", len(detail.Sessions))
	}

	hash := detail.Commit.Hash
	if hash == "" {
		hash = detail.Commit.ShortHash
	}
	if hash != "" {
		fmt.Fprintf(&sb, "Commit: %s\n", hash)
	}
	if detail.Commit.Author != "" {
		fmt.Fprintf(&sb, "Author: %s\n", detail.Commit.Author)
	}
	if detail.Commit.WhenText != "" {
		fmt.Fprintf(&sb, "When: %s\n", detail.Commit.WhenText)
	}
	if detail.Commit.Subject != "" {
		fmt.Fprintf(&sb, "Subject: %s\n", detail.Commit.Subject)
	}
	if len(detail.FilesTouched) > 0 {
		fmt.Fprintf(&sb, "Files: %s\n", strings.Join(detail.FilesTouched, ", "))
	}
	return sb.String()
}

