func (m whyModel) renderBrowserContent() string {
	var b strings.Builder
	if len(m.browserEntries) == 0 {
		b.WriteString(m.styles.render(m.styles.dim, "No files or directories found."))
		return b.String()
	}

	for i, entry := range m.browserEntries {
		icon := "FILE"
		name := entry.Name
		if entry.IsDir {
			icon = "DIR "
			name += string(os.PathSeparator)
		}
		line := fmt.Sprintf("%s  %-4s  %s", ternaryWhy(i == m.browserCursor, ">", " "), icon, name)
		if m.styles.colorEnabled {
			switch {
			case i == m.browserCursor:
				line = m.styles.render(m.styles.selected, line)
			case entry.IsDir:
				line = m.styles.render(m.styles.cyan, line)
			}
		}
		b.WriteString(line)
		if i < len(m.browserEntries)-1 {
			b.WriteString("\n")
		}
	}
	return b.String()
}

func (m whyModel) renderBrowseContent() string {
	var b strings.Builder
	if len(m.rows) == 0 {
		b.WriteString(m.styles.render(m.styles.dim, "No blamed lines found."))
		return b.String()
	}

	codeLines := highlightWhyCodeLines(m.path, m.rows)
	for i, row := range m.rows {
		line := renderWhyBrowseRow(row, codeLines[i], m.width, i == m.cursor)
		if m.styles.colorEnabled {
			line = m.styleWhyBrowseRow(line, row, i == m.cursor)
		}
		b.WriteString(line)
		if i < len(m.rows)-1 {
			b.WriteString("\n")
		}
	}

