	line = strings.Replace(line, whyRowCommitHash(row), m.styles.render(m.styles.cyan, whyRowCommitHash(row)), 1)
	if row.Entire != nil && row.Entire.CheckpointID != "" {
		line = strings.Replace(line, row.Entire.CheckpointID, m.styles.render(m.styles.checkpoint, row.Entire.CheckpointID), 1)
	}
	if selected {
		return m.styles.render(m.styles.selected, line)
	}
	return line
}

func highlightWhyCodeLines(path string, rows []whyRow) []string {
	if len(rows) == 0 {
		return nil
	}

	codeLines := make([]string, 0, len(rows))
	for _, row := range rows {
		codeLines = append(codeLines, row.CodeLine)
	}

	highlighted := renderWhyHighlightedCode(path, strings.Join(codeLines, "\n"))
	split := strings.Split(highlighted, "\n")
	if len(split) != len(codeLines) {
		return codeLines
	}
	return split
}

