func (m whyModel) renderSessionDetailContent() string {
	if m.sessionDetail == nil {
		return ""
	}
	detail := *m.sessionDetail
	detail.Transcript = collapseWhyToolCalls(detail.Transcript, m.toolCallsExpanded)
	return m.styleWhyDetailContent(renderWhySessionDetail(detail))
}

func (m whyModel) styleWhyDetailContent(content string) string {
	if !m.styles.colorEnabled || strings.TrimSpace(content) == "" {
		return content
	}

	lines := strings.Split(content, "\n")
	for i, line := range lines {
		switch {
		case strings.HasPrefix(line, "==="):
			lines[i] = m.styles.render(m.styles.detailTitle, line)
		case strings.HasPrefix(line, "[Assistant]"):
			lines[i] = m.styles.render(m.styles.assistant, "[Assistant]") + strings.TrimPrefix(line, "[Assistant]")
		case strings.HasPrefix(line, "[User]"):
			lines[i] = m.styles.render(m.styles.user, "[User]") + strings.TrimPrefix(line, "[User]")
		case strings.HasPrefix(line, "[Tools]"), strings.HasPrefix(line, "[Tool]"):
			prefix := "[Tools]"
			if strings.HasPrefix(line, "[Tool]") {
				prefix = "[Tool]"
			}
			lines[i] = m.styles.render(m.styles.tool, prefix) + strings.TrimPrefix(line, prefix)
		case strings.Contains(line, ": "):
			lines[i] = m.styleWhyLabelLine(line)
		}
	}
	return strings.Join(lines, "\n")
}

func (m whyModel) styleWhyLabelLine(line string) string {
	label, value, ok := strings.Cut(line, ": ")
	if !ok {
		return line
	}
	renderedValue := value
	switch label {
	case "Checkpoint", "Commit", "Transcript ID":
		renderedValue = m.styles.render(m.styles.checkpoint, value)
	case "Agent":
		renderedValue = m.styles.render(m.styles.agent, value)
	case "Tokens":
		renderedValue = m.styles.render(m.styles.token, value)
	case "Generated Summary", "Fallback Summary", "Subject", "Session", "Model":
		renderedValue = m.styles.render(m.styles.bold, value)
	case "Author", "When", "Created", "Files", "Checkpoints":
		renderedValue = value
	}
	return m.styles.render(m.styles.label, label+":") + " " + renderedValue
}

func (m whyModel) styleWhySessionRow(row string) string {
	if !m.styles.colorEnabled {
		return row
	}
	row = strings.Replace(row, "Claude Code", m.styles.render(m.styles.agent, "Claude Code"), 1)
	row = strings.Replace(row, "Fallback", m.styles.render(m.styles.yellow, "Fallback"), 1)
	row = strings.Replace(row, "Generated", m.styles.render(m.styles.cyan, "Generated"), 1)
	return row
}

func collapseWhyToolCalls(transcript string, expanded bool) string {
	if expanded || strings.TrimSpace(transcript) == "" {
		return transcript
	}

	lines := strings.Split(transcript, "\n")
	out := make([]string, 0, len(lines))
	i := 0
	for i < len(lines) {
		if !strings.HasPrefix(lines[i], "[Tool] ") {
			out = append(out, lines[i])
			i++
			continue
		}

		start := i
		toolCount := 0
		for i < len(lines) {
			switch {
			case strings.HasPrefix(lines[i], "[Tool] "):
				toolCount++
				i++
			case strings.TrimSpace(lines[i]) == "":
				i++
			default:
				goto done
			}
		}
	done:
		if toolCount <= 1 {
			out = append(out, lines[start:i]...)
			continue
		}
		out = append(out, fmt.Sprintf("[Tools] %d tool calls (press e to expand)", toolCount))

