	origLoadWhyCheckpointDetail := loadWhyCheckpointDetail
	origLoadWhySessionDetail := loadWhySessionDetail
	t.Cleanup(func() {
		loadWhyCheckpointDetail = origLoadWhyCheckpointDetail
		loadWhySessionDetail = origLoadWhySessionDetail
	})

	loadWhyCheckpointDetail = func(_ context.Context, _ string, block whyBlock) (*whyCheckpointDetail, error) {
		return &whyCheckpointDetail{
			Commit: block.Commit,
			Entire: *block.Entire,
			Sessions: []whySessionSummary{
				{Index: 0, SessionID: "session-a", Agent: "Claude Code", Model: "claude-sonnet"},
			},
		}, nil
	}
	loadWhySessionDetail = func(_ context.Context, checkpointDetail *whyCheckpointDetail, sessionIndex int) (*whySessionDetail, error) {
		return &whySessionDetail{
			Commit:     checkpointDetail.Commit,
			Checkpoint: checkpointDetail.Entire.CheckpointID,
			Session:    checkpointDetail.Sessions[sessionIndex],
			Transcript: strings.Join([]string{
				"[Assistant] I inspected the file.",
				"[Tool] Read: /tmp/a.go",
				"[Tool] Read: /tmp/a.go",
				"[Tool] Read: /tmp/a.go",
				"[Tool] Read: /tmp/a.go",
				"[Assistant] Done.",
			}, "\n"),
		}, nil
	}

