	}

	collapsed := m.detailVP.View()
	if !strings.Contains(collapsed, "[Tools] 4 tool calls (press e to expand)") {
		t.Fatalf("session detail should collapse tool calls by default:\n%s", collapsed)
	}
	if strings.Contains(collapsed, "[Tool] Read: /tmp/a.go") {
		t.Fatalf("session detail should hide raw tool calls by default:\n%s", collapsed)
	}

