	expanded := m.detailVP.View()
	if !strings.Contains(expanded, "[Tool] Read: /tmp/a.go") {
		t.Fatalf("session detail should expand raw tool calls on demand:\n%s", expanded)
	}
	if strings.Contains(expanded, "[Tools] 4 tool calls (press e to expand)") {
		t.Fatalf("expanded session detail should not keep collapsed summary:\n%s", expanded)
	}
}

