package cli

import (
	"strings"
	"testing"
)

func TestRenderWhyStatic_IncludesEntireFields(t *testing.T) {
	t.Parallel()

	out := renderWhyStatic([]whyBlock{{
		StartLine: 23,
		EndLine:   24,
		Commit: whyCommitInfo{
			ShortHash: "b550507521",
			Author:    "Victor Gutierrez",
			WhenText:  "2 weeks ago",
		},
		Entire: &whyEntireInfo{
			CheckpointID: "a3b2c4d5e6f7",
			Agent:        "Claude Code",
			Summary:      "Add signal handling for graceful shutdown.",
		},
		CodeLines: []string{"if runtime.GOOS != \"windows\" {", "\treturn"},
	}})

	for _, want := range []string{
		"COMMIT",
		"AUTHOR",
		"CHECKPOINT",
		"AGENT",
		"LINE",
		"b550507521",
		"Victor Gutierrez",
		"a3b2c4d5e6f7",
		"Claude Code",
		"23",
		"24",
		"if runtime.GOOS != \"windows\" {",
		"\treturn",
	} {
		if !strings.Contains(out, want) {
			t.Fatalf("output missing %q:\n%s", want, out)
		}
	}

	if strings.Contains(out, "Lines 23-24") {
		t.Fatalf("static output should render per-file rows, not block headers:\n%s", out)
	}
}

func TestRenderWhyCommitDetail_IncludesCommitMetadataAndDiff(t *testing.T) {
	t.Parallel()

	out := renderWhyCommitDetail(whyCommitDetail{
		Commit: whyCommitInfo{
			Hash:      "b550507521111111111111111111111111111111",
			ShortHash: "b550507521",
			Author:    "Victor Gutierrez",
			WhenText:  "2 weeks ago",
			Subject:   "Handle interrupt signals",
		},
		Diff: "@@ -1,2 +1,3 @@\n+signal.Notify(sigChan, signals...)\n",
	})

	for _, want := range []string{
		"b550507521111111111111111111111111111111",
		"Victor Gutierrez",
		"2 weeks ago",
		"Handle interrupt signals",
		"Diff:",
		"@@ -1,2 +1,3 @@",
		"Notify",
		"sigChan",
		"signals",
	} {
		if !strings.Contains(out, want) {
			t.Fatalf("output missing %q:\n%s", want, out)
		}
	}
}

