func (m whyModel) updateDetailMode(msg tea.KeyMsg) (tea.Model, tea.Cmd) { //nolint:ireturn // bubbletea pattern
	if next, handled := m.handlePagerJumpDetail(msg); handled {
		return next, nil
	}

	if m.checkpointDetail != nil {
		switch msg.String() {
		case "tab":
			if len(m.checkpointDetail.Sessions) > 0 && m.checkpointDetail.Diff != "" {
				if m.detailFocus == whyDetailFocusSessions {
					m.detailFocus = whyDetailFocusDiff
				} else {
					m.detailFocus = whyDetailFocusSessions
				}
				m.detailVP.SetContent(m.renderCheckpointDetail())
			}
			return m, nil
		case "esc", "backspace", "h", "left":
			m.mode = whyModeBrowse
			m.checkpointDetail = nil
			m.sessionDetail = nil
			return m, nil
		case "up", "k":
			if m.detailFocus == whyDetailFocusDiff {
				m.detailVP.LineUp(1)
				return m, nil
			}
			if m.sessionCursor > 0 {
				m.sessionCursor--
				m.detailVP.SetContent(m.renderCheckpointDetail())
			}
			return m, nil
		case "down", "j":
			if m.detailFocus == whyDetailFocusDiff {
				m.detailVP.LineDown(1)
				return m, nil
			}
			if m.sessionCursor < len(m.checkpointDetail.Sessions)-1 {
				m.sessionCursor++
				m.detailVP.SetContent(m.renderCheckpointDetail())
			}
			return m, nil
		case "enter", " ", "l", "right":
			if m.detailFocus == whyDetailFocusDiff {
				return m, nil
			}
