			Commit: whyCommitInfo{
				Hash:      "7f93a963e3abcdef",
				ShortHash: "7f93a963e3",
				Author:    "Stefan Haubold",
			},
			Detail:    whyDetailCommit,
			CodeLines: []string{"func main() {", "}"},
		},
	})

	if len(rows) != 4 {
		t.Fatalf("row count = %d, want 4", len(rows))
	}

	if got, want := rows[0].LineNumber, 1; got != want {
		t.Fatalf("first line number = %d, want %d", got, want)
	}
	if got, want := rows[1].CodeLine, ""; got != want {
		t.Fatalf("second code line = %q, want blank line", got)
	}
	if rows[0].Entire == nil {
		t.Fatal("expected Entire metadata on first row")
