	}
	if got, want := rows[0].BlockEndLine, 2; got != want {
		t.Fatalf("first block end = %d, want %d", got, want)
	}
	if got, want := rows[2].LineNumber, 3; got != want {
		t.Fatalf("third line number = %d, want %d", got, want)
	}
	if got, want := rows[2].Commit.ShortHash, "7f93a963e3"; got != want {
		t.Fatalf("third row short hash = %q, want %q", got, want)
	}
	if got, want := rows[2].Detail, whyDetailCommit; got != want {
		t.Fatalf("third row detail = %q, want %q", got, want)
	}
}

