var getWhyBrowserRoot = os.Getwd

var readWhyBrowserDir = os.ReadDir

func newWhyModel(ctx context.Context, path string, blocks []whyBlock, ss statusStyles) whyModel {
	m := whyModel{
		ctx:      ctx,
		path:     path,
		blocks:   blocks,
		rows:     flattenWhyRows(blocks),
		width:    ss.width,
		mode:     whyModeBrowse,
		styles:   newWhyStyles(ss),
		browseVP: viewport.New(ss.width, 1),
	}
	return m.refreshBrowseContent()
}

func newWhyBrowserModel(ctx context.Context, ss statusStyles) (whyModel, error) {
	root, err := getWhyBrowserRoot()
	if err != nil {
		return whyModel{}, fmt.Errorf("get current directory: %w", err)
	}

	m := whyModel{
		ctx:       ctx,
		width:     ss.width,
		mode:      whyModeBrowser,
		styles:    newWhyStyles(ss),
		browserVP: viewport.New(ss.width, 1),
		browseVP:  viewport.New(ss.width, 1),
	}
	return m.loadWhyBrowserDir(root, "", 0, false)
}

func (m whyModel) Init() tea.Cmd {
	return nil
}

func (m whyModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) { //nolint:ireturn,cyclop // bubbletea interface
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.browserVP.Width = msg.Width
		m.browserVP.Height = max(msg.Height-4, 1)
		m.browseVP.Width = msg.Width
		m.browseVP.Height = max(msg.Height-4, 1)
		if m.mode == whyModeDetail || m.mode == whyModeSessionDetail {
			m.detailVP.Width = msg.Width
			m.detailVP.Height = max(msg.Height-3, 1)
		}
		if m.mode == whyModeBrowser {
			m = m.refreshBrowserContent()
			return m, nil
		}
		m = m.refreshBrowseContent()
		return m, nil
	case tea.KeyMsg:
		switch m.mode {
		case whyModeBrowser:
			return m.updateBrowserMode(msg)
		case whyModeDetail:
			return m.updateDetailMode(msg)
		case whyModeSessionDetail:
			return m.updateSessionDetailMode(msg)
		default:
			return m.updateBrowseMode(msg)
		}
	}

	return m, nil
}

func (m whyModel) updateBrowserMode(msg tea.KeyMsg) (tea.Model, tea.Cmd) { //nolint:ireturn // bubbletea pattern
	if next, handled := m.handlePagerJumpBrowser(msg); handled {
		return next, nil
	}

	switch msg.String() {
	case "q", "ctrl+c":
		return m, tea.Quit
	case "esc", "h":
		next, err := m.ascendWhyBrowserDir()
		if err != nil {
			m.browserErr = err.Error()
			m = m.refreshBrowserContent()
			return m, nil
		}
		return next, nil
	case "up", "k":
		if m.browserCursor > 0 {
			m.browserCursor--
			m = m.refreshBrowserContent()
		}
	case "down", "j":
		if m.browserCursor < len(m.browserEntries)-1 {
			m.browserCursor++
			m = m.refreshBrowserContent()
		}
	case "left", "backspace":
		next, err := m.ascendWhyBrowserDir()
		if err != nil {
			m.browserErr = err.Error()
			m = m.refreshBrowserContent()
			return m, nil
		}
		return next, nil
	case "right", "l", "enter", " ":
		entry := m.selectedBrowserEntry()
		if entry == nil {
			return m, nil
		}
		if !entry.IsDir {
			next, err := m.openWhyBrowserFile(entry.Path)
			if err != nil {
				m.browserErr = err.Error()
				m = m.refreshBrowserContent()
				return m, nil
			}
			return next, nil
		}
		next, err := m.loadWhyBrowserDir(entry.Path, "", 0, true)
		if err != nil {
			m.browserErr = err.Error()
			m = m.refreshBrowserContent()
			return m, nil
		}
		return next, nil
	default:
		var cmd tea.Cmd
		m.browserVP, cmd = m.browserVP.Update(msg)
		return m, cmd
	}

		}
		return renderWhyCommitDetail(whyCommitDetail{
			Commit: block.Commit,
			Diff:   diff,
		})
	}
}

func (m whyModel) renderCheckpointDetail() string {
	if m.checkpointDetail == nil {
		return ""
	}

	var sb strings.Builder
	sb.WriteString(m.styleWhyDetailContent(renderWhyCheckpointMetadata(*m.checkpointDetail)))
	if len(m.checkpointDetail.Sessions) > 0 {
		if sb.Len() > 0 {
			sb.WriteString("\n\n")
		}
		var section strings.Builder
		title := "=== Sessions (j/k to select, enter to open) ==="
		if m.detailFocus == whyDetailFocusSessions && m.checkpointDetail.Diff != "" {
			title = "=== Sessions (focused: j/k select, tab switches to diff) ==="
		}
		section.WriteString(m.styles.render(m.styles.detailTitle, title))
		section.WriteString("\n")
		section.WriteString(m.styles.render(m.styles.tableHeader, "    ID           AGENT         MODEL                TOKENS                    CREATED              TYPE                 SUMMARY"))
		section.WriteString("\n")
		for i, session := range m.checkpointDetail.Sessions {
			prefix := "  "
			if i == m.sessionCursor {
				prefix = "> "
			}
			row := fmt.Sprintf("%s[%d] %-12s %-13s %-20s %-24s %-20s %-20s %s",
				prefix,
				i+1,
				session.SessionID,
				emptyWhyValue(session.Agent, "-"),
				emptyWhyValue(session.Model, "-"),
				truncateWhyDisplayField(emptyWhyValue(session.TokenUsage, "-"), 24),
				emptyWhyValue(session.CreatedAtText, "-"),
				truncateWhyDisplayField(sessionSummaryLabel(session), 20),
				truncateWhyDisplayField(emptyWhyValue(session.Summary, "-"), 60),
			)
			if m.styles.colorEnabled {
				if i == m.sessionCursor {
					row = m.styles.render(m.styles.selected, row)
				} else {
					row = m.styleWhySessionRow(row)
				}
			}
			section.WriteString(row)
			section.WriteString("\n")
		}
		sb.WriteString(m.renderWhyDetailSection(strings.TrimRight(section.String(), "\n"), false, m.detailFocus == whyDetailFocusSessions))
	} else {
		if sb.Len() > 0 {
			sb.WriteString("\n\n")
		}
		section := strings.Join([]string{
			m.styles.render(m.styles.detailTitle, "=== Sessions ==="),
			m.styles.render(m.styles.dim, "No sessions available."),
		}, "\n")
		sb.WriteString(m.renderWhyDetailSection(section, false, false))
	}
	if strings.TrimSpace(m.checkpointDetail.GeneratedSummary) != "" {
		if sb.Len() > 0 {
			sb.WriteString("\n\n")
		}
		var section strings.Builder
		title := "=== Generated Checkpoint Summary ==="
		if m.detailFocus == whyDetailFocusSummary {
			title = "=== Generated Checkpoint Summary (focused: j/k scroll, tab switches pane) ==="
		} else if m.hasWhyDetailFocusCycle() {
			title = "=== Generated Checkpoint Summary (tab to focus) ==="
		}
		section.WriteString(m.styles.render(m.styles.detailTitle, title))
		section.WriteString("\n")
		section.WriteString(m.styles.render(m.styles.bold, m.checkpointDetail.GeneratedSummary))
		sb.WriteString(m.renderWhyDetailSection(strings.TrimRight(section.String(), "\n"), false, m.detailFocus == whyDetailFocusSummary))
	}
	if m.checkpointDetail.Diff != "" {
		if sb.Len() > 0 {
			sb.WriteString("\n\n")
		}
		var section strings.Builder
		title := "=== File Diff ==="
		if len(m.checkpointDetail.Sessions) > 0 {
			if m.detailFocus == whyDetailFocusDiff {
				title = "=== File Diff (focused: j/k scroll, tab switches to sessions) ==="
			} else {
				title = "=== File Diff (tab to focus) ==="
			}
		}
		section.WriteString(m.styles.render(m.styles.detailTitle, title))
		section.WriteString("\n")
		section.WriteString(renderWhyHighlightedDiff(m.checkpointDetail.Diff))
		if !strings.HasSuffix(m.checkpointDetail.Diff, "\n") {
			section.WriteString("\n")
		}
		sb.WriteString(m.renderWhyDetailSection(strings.TrimRight(section.String(), "\n"), true, m.detailFocus == whyDetailFocusDiff))
	}
	return strings.TrimRight(sb.String(), "\n")
}

func (m whyModel) renderWhyDetailSection(content string, codeSection, focused bool) string {
	if !m.styles.colorEnabled || strings.TrimSpace(content) == "" {
		return content
	}

	style := m.styles.panelBorder
	if codeSection {
		style = m.styles.codeBorder
	}
	if focused {
		style = style.Copy().BorderForeground(lipgloss.Color("214"))
	}
	return style.Render(content)
}

func (m whyModel) whyDetailFocusOrder() []whyDetailFocus {
	if m.checkpointDetail == nil {
		return nil
	}

	order := make([]whyDetailFocus, 0, 3)
	if len(m.checkpointDetail.Sessions) > 0 {
		order = append(order, whyDetailFocusSessions)
	}
	if strings.TrimSpace(m.checkpointDetail.GeneratedSummary) != "" {
		order = append(order, whyDetailFocusSummary)
	}
	if m.checkpointDetail.Diff != "" {
		order = append(order, whyDetailFocusDiff)
	}
	return order
}

func (m whyModel) hasWhyDetailFocusCycle() bool {
	return len(m.whyDetailFocusOrder()) > 1
}

func (m whyModel) nextWhyDetailFocus() (whyDetailFocus, bool) {
	order := m.whyDetailFocusOrder()
	if len(order) <= 1 {
		return 0, false
	}
	for i, focus := range order {
		if focus == m.detailFocus {
			return order[(i+1)%len(order)], true
		}
	}
	return order[0], true
}

func sessionSummaryLabel(session whySessionSummary) string {
	if session.IsFallback {
