}

func newWhyBrowserModel(ctx context.Context, ss statusStyles) (whyModel, error) {
	root, err := getWhyBrowserRoot()
	if err != nil {
		return whyModel{}, fmt.Errorf("get current directory: %w", err)
	}

	m := whyModel{
		ctx:       ctx,
		width:     ss.width,
		mode:      whyModeBrowser,
		styles:    newWhyStyles(ss),
		browserVP: viewport.New(ss.width, 1),
		browseVP:  viewport.New(ss.width, 1),
	}
	return m.loadWhyBrowserDir(root, "", 0, false)
}

func (m whyModel) Init() tea.Cmd {
	return nil
}

func (m whyModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) { //nolint:ireturn,cyclop // bubbletea interface
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.browserVP.Width = msg.Width
		m.browserVP.Height = max(msg.Height-4, 1)
		m.browseVP.Width = msg.Width
		m.browseVP.Height = max(msg.Height-4, 1)
		if m.mode == whyModeDetail || m.mode == whyModeSessionDetail {
			m.detailVP.Width = msg.Width
			m.detailVP.Height = max(msg.Height-3, 1)
		}
		if m.mode == whyModeBrowser {
			m = m.refreshBrowserContent()
			return m, nil
		}
		m = m.refreshBrowseContent()
		return m, nil
	case tea.KeyMsg:
		switch m.mode {
		case whyModeBrowser:
			return m.updateBrowserMode(msg)
		case whyModeDetail:
			return m.updateDetailMode(msg)
		case whyModeSessionDetail:
			return m.updateSessionDetailMode(msg)
		default:
			return m.updateBrowseMode(msg)
		}
	}

	return m, nil
}

func (m whyModel) updateBrowserMode(msg tea.KeyMsg) (tea.Model, tea.Cmd) { //nolint:ireturn // bubbletea pattern
	if next, handled := m.handlePagerJumpBrowser(msg); handled {
		return next, nil
	}

	switch msg.String() {
	case "q", "ctrl+c":
		return m, tea.Quit
	case "esc", "h":
		next, err := m.ascendWhyBrowserDir()
		if err != nil {
			m.browserErr = err.Error()
			m = m.refreshBrowserContent()
			return m, nil
		}
		return next, nil
	case "up", "k":
		if m.browserCursor > 0 {
			m.browserCursor--
			m = m.refreshBrowserContent()
		}
	case "down", "j":
		if m.browserCursor < len(m.browserEntries)-1 {
			m.browserCursor++
			m = m.refreshBrowserContent()
		}
	case "left", "backspace":
		next, err := m.ascendWhyBrowserDir()
		if err != nil {
			m.browserErr = err.Error()
			m = m.refreshBrowserContent()
			return m, nil
		}
		return next, nil
	case "right", "l", "enter", " ":
		entry := m.selectedBrowserEntry()
		if entry == nil {
			return m, nil
		}
		if !entry.IsDir {
			next, err := m.openWhyBrowserFile(entry.Path)
			if err != nil {
				m.browserErr = err.Error()
				m = m.refreshBrowserContent()
				return m, nil
			}
			return next, nil
		}
		next, err := m.loadWhyBrowserDir(entry.Path, "", 0, true)
		if err != nil {
			m.browserErr = err.Error()
			m = m.refreshBrowserContent()
			return m, nil
		}
		return next, nil
	default:
		var cmd tea.Cmd
		m.browserVP, cmd = m.browserVP.Update(msg)
		return m, cmd
	}

