var openWhyRepository = openRepository

func withWhyRepository(ctx context.Context, repo *git.Repository) context.Context {
	if repo == nil {
		return ctx
	}
	return context.WithValue(ctx, whyRepoContextKey{}, repo)
}

func whyRepositoryFromContext(ctx context.Context) *git.Repository {
	repo, _ := ctx.Value(whyRepoContextKey{}).(*git.Repository)
	return repo
