	var (
		interactiveFlag bool
		noPagerFlag     bool
		linesFlag       string
	)

	cmd := &cobra.Command{
		Use:   "why [path]",
		Short: "Show why lines exist in a file",
		Args:  cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			out := cmd.OutOrStdout()
			canRunInteractive := shouldRunWhyTUI(out)
			wantsInteractive := interactiveFlag || canRunInteractive
			var lineRange *whyLineRange

			if strings.TrimSpace(linesFlag) != "" {
				parsedRange, err := parseWhyLineRange(linesFlag)
				if err != nil {
					return err
				}
				lineRange = &parsedRange
			}

			if interactiveFlag && !canRunInteractive {
				return errors.New("--interactive requires an interactive terminal and is unavailable in accessible mode")
			}
			if len(args) == 0 {
				if !wantsInteractive {
					return errors.New("path required when using accessible mode, piped output, or non-interactive mode. Usage: entire why <path>")
				}
				if err := runWhyTUIBrowser(ctx, out); err != nil {
					return fmt.Errorf("TUI error: %w", err)
				}
				return nil
			}

			blocks, err := loadWhyDisplayData(ctx, args[0], lineRange)
			if err != nil {
				return fmt.Errorf("loading why data for %s: %w", args[0], err)
			}

			if wantsInteractive {
				if err := runWhyTUI(ctx, out, args[0], blocks); err != nil {
					return fmt.Errorf("TUI error: %w", err)
				}
				return nil
			}

			outputWhyContent(out, renderWhyStatic(blocks), noPagerFlag)
			return nil
		},
	}

	cmd.Flags().BoolVarP(&interactiveFlag, "interactive", "i", false, "Show the interactive TUI")
	cmd.Flags().BoolVar(&noPagerFlag, "no-pager", false, "Disable pager output")
	cmd.Flags().StringVarP(&linesFlag, "lines", "L", "", "Restrict blame to a line or line range (e.g. 23 or 23-42)")

	return cmd
}

