		}, "\n")
		sb.WriteString(m.renderWhyDetailSection(section, false, false))
	}
	if strings.TrimSpace(m.checkpointDetail.GeneratedSummary) != "" {
		if sb.Len() > 0 {
			sb.WriteString("\n\n")
		}
		var section strings.Builder
		title := "=== Generated Checkpoint Summary ==="
		if m.detailFocus == whyDetailFocusSummary {
			title = "=== Generated Checkpoint Summary (focused: j/k scroll, tab switches pane) ==="
		} else if m.hasWhyDetailFocusCycle() {
			title = "=== Generated Checkpoint Summary (tab to focus) ==="
		}
		section.WriteString(m.styles.render(m.styles.detailTitle, title))
		section.WriteString("\n")
		summaryContent := m.checkpointDetail.GeneratedSummary
		if m.detailFocus != whyDetailFocusSummary {
			summaryContent = previewWhyTextLines(summaryContent, 6, "... (tab to focus summary)")
		}
		section.WriteString(m.styles.render(m.styles.bold, summaryContent))
		sb.WriteString(m.renderWhyDetailSection(strings.TrimRight(section.String(), "\n"), false, m.detailFocus == whyDetailFocusSummary))
	}
	if m.checkpointDetail.Diff != "" {
		if sb.Len() > 0 {
			sb.WriteString("\n\n")
		}
		var section strings.Builder
		title := "=== File Diff ==="
		if len(m.checkpointDetail.Sessions) > 0 {
			if m.detailFocus == whyDetailFocusDiff {
				title = "=== File Diff (focused: j/k scroll, tab switches to sessions) ==="
			} else {
				title = "=== File Diff (tab to focus) ==="
			}
		}
		section.WriteString(m.styles.render(m.styles.detailTitle, title))
		section.WriteString("\n")
		diffContent := renderWhyHighlightedDiff(m.checkpointDetail.Diff)
		if m.detailFocus != whyDetailFocusDiff {
			diffContent = previewWhyTextLines(diffContent, 10, "... (tab to focus diff)")
		}
		section.WriteString(diffContent)
		if !strings.HasSuffix(diffContent, "\n") {
			section.WriteString("\n")
		}
		sb.WriteString(m.renderWhyDetailSection(strings.TrimRight(section.String(), "\n"), true, m.detailFocus == whyDetailFocusDiff))
	}
	return strings.TrimRight(sb.String(), "\n")
}

func previewWhyTextLines(content string, maxLines int, trailer string) string {
	if maxLines <= 0 {
		return strings.TrimSpace(trailer)
	}

	lines := strings.Split(strings.TrimRight(content, "\n"), "\n")
	if len(lines) <= maxLines {
		return content
	}

	preview := append([]string(nil), lines[:maxLines]...)
	if strings.TrimSpace(trailer) != "" {
		preview = append(preview, trailer)
	}
	return strings.Join(preview, "\n")
}

func (m whyModel) renderWhyDetailSection(content string, codeSection, focused bool) string {
	if !m.styles.colorEnabled || strings.TrimSpace(content) == "" {
		return content
	}

	style := m.styles.panelBorder
	if codeSection {
		style = m.styles.codeBorder
	}
	if focused {
		style = style.Copy().BorderForeground(lipgloss.Color("214"))
	}
	return style.Render(content)
}

func (m whyModel) whyDetailFocusOrder() []whyDetailFocus {
	if m.checkpointDetail == nil {
		return nil
	}

	order := make([]whyDetailFocus, 0, 3)
	if len(m.checkpointDetail.Sessions) > 0 {
		order = append(order, whyDetailFocusSessions)
	}
	if strings.TrimSpace(m.checkpointDetail.GeneratedSummary) != "" {
		order = append(order, whyDetailFocusSummary)
	}
	if m.checkpointDetail.Diff != "" {
		order = append(order, whyDetailFocusDiff)
	}
	return order
}

func (m whyModel) hasWhyDetailFocusCycle() bool {
	return len(m.whyDetailFocusOrder()) > 1
}

func (m whyModel) nextWhyDetailFocus() (whyDetailFocus, bool) {
	order := m.whyDetailFocusOrder()
	if len(order) <= 1 {
		return 0, false
	}
	for i, focus := range order {
		if focus == m.detailFocus {
			return order[(i+1)%len(order)], true
		}
	}
	return order[0], true
}

